export const QUESTIONS = [{"year":2009,"qno":41,"subject":"数据结构","type":"证明/简答题（最短路径）","title":"贪心逐跳能否求最短路径","score":"10分","budgetMin":"8","detail":"题干给的是一个按局部最优逐跳推进的求最短路径方法，问它是否总能得到最短路径，结论是“不一定能”。因为一次局部最优的选择可能把后续路线带进死路：反例里顶点 1 到 4 的真实最短长度为 2，而该方法得到 3，1 到 3 甚至求不出路径。考场上先亮结论，再用一个小图把反例画清楚，最后补一句“局部最优≠全局最优”，不必做严格证明。","kp":["最短路径","贪心策略","局部最优","反例构造"],"answerKey":["不一定能（或不能）求得最短路径（4分）","反例1：顶点1到4最短长2，该方法得3","反例2：1到3求不出路径（6分）","本质：局部最优≠全局最优"],"mustWrite":["结论：不一定能求得最短路径","举一个反例说明","答出局部最优≠全局最优"],"skip":["写“能求得”一律0分","不必严格证明，举例即可"],"pitfalls":["只下结论不举例，丢6分"]},{"year":2009,"qno":42,"subject":"数据结构","type":"算法设计题（链表）","title":"链表倒数第 k 个结点","score":"15分","budgetMin":"12","detail":"要求只扫一趟就定位单链表的倒数第 k 个结点，标准解法是双指针：p、q 先同指首结点，p 先走 k 步，然后 p、q 同步后移，p 到尾时 q 正好落在倒数第 k 个位置。关键是先判 k 是否超过表长，超长应返回 0；若先求表长再走第二遍，或借助与 k 相关的辅助数组，都拿不到满分。答题时写出类型定义、双指针步骤和核心代码即可。","kp":["单链表","双指针","倒数第k个结点","一趟扫描"],"answerKey":["定义p、q均指向第一个结点","p先走k步后q与p同步走","p到尾时q即倒数第k个，仅一趟扫描","一趟扫描满分15；两遍/递归/额外数组最高10分"],"mustWrite":["双指针同步走的设计思想","核心代码（一趟扫描）与返回1/0","类型定义与步骤描述"],"skip":["别先求表长再走第二遍（最高10分）","别用与k有关的辅助数组"],"pitfalls":["k超表长未判断，应返回0"]},{"year":2009,"qno":43,"subject":"计算机组成原理","type":"计算题（中断/DMA）","title":"中断与 DMA 开销对比计算","score":"8分","budgetMin":"10","detail":"这题考的是把 I/O 方式的额外开销折算成 CPU 时间占比：中断方式要先由每次中断的开销周期数乘上每秒中断次数，再除以主频得到占比；DMA 则按每次传送的数据块大小算出每秒传送次数，乘上每次 DMA 的周期开销。两条线都要写出“次数×每次开销”的算式，只给百分比每个只能拿 2 分。易错点在于 MB 与字节、时钟频率与周期之间的单位换算，务必先把单位统一。","kp":["中断","DMA","中断开销","CPU占用率"],"answerKey":["中断：每次开销5×18+5×2=100周期","0.5MB/s÷4B=125000次/s","开销12.5M周期，占12.5M/500M=2.5%","DMA：5MB÷5000B=1000次，1000×500=0.5M，占0.1%"],"mustWrite":["中断2.5%、DMA 0.1%两个百分比","计算过程（次数×每次开销）"],"skip":["只写结果不写过程，每个仅2分"],"pitfalls":["MB与时钟周期单位换算错"]},{"year":2009,"qno":44,"subject":"计算机组成原理","type":"分析题（数据通路）","title":"数据通路节拍与控制信号","score":"（未标）","budgetMin":"12","detail":"题目给出寄存器与主存之间的数据通路，要求写出各节拍的微操作及配套控制信号。做法是按“读操作数—ALU 运算—写回主存”分段，每一拍只写一个数据传送，并配上对应的 out/in 及使能信号（如 MDRinE、MDRoutE、MemR、MemW）。答题时先列节拍功能再列信号，成对出现才不丢分；题干已给的取指示例不必照抄，把笔墨留给读写数据段。","kp":["数据通路","控制信号","微操作","节拍划分"],"answerKey":["C5:(R1)→MAR；C6:M(MAR)→MDR","C7:(MDR)→A；C8:(A)+(R0)→AC","C9:(AC)→MDR；C10:(MDR)→M(MAR)","控制信号：R1out/MARin/MemR/MDRinE；MDRout/(R0)out/Add/ACin；ACout/MDRin/MDRoutE/MemW"],"mustWrite":["节拍功能+控制信号","分读、写回两段"],"skip":["不必抄题干的取指示例"],"pitfalls":["漏MemR/MemW/MDRinE等信号"]},{"year":2009,"qno":45,"subject":"操作系统","type":"PV操作题","title":"奇偶数分拣的 PV 同步设计","score":"（未标）","budgetMin":"10","detail":"这是带分类取用的生产者—消费者变体：放产品的进程要受空缓冲区数量约束，两个取产品的进程分别只取奇数与偶数，因此除互斥信号量外还要按类别各设一个同步信号量。正确做法是先把互斥与三类同步信号量及其初值列全，再写“先 P 资源信号量、后 P 互斥信号量，操作完 V 互斥、再 V 资源”的顺序。最致命的错误是取方漏掉 V(empty)，缓冲区很快占满导致死锁。","kp":["PV操作","信号量","同步与互斥","缓冲区"],"answerKey":["mutex=1；empty=N；odd=0；even=0","P1:P(empty),P(mutex),put,V(mutex)，奇数V(odd)偶数V(even)","P2/P3：先P(odd)（P2）/P(even)（P3），再P(mutex),get,V(mutex),V(empty)"],"mustWrite":["四个信号量及初值1/N/0/0","先P(empty)后P(mutex)，取后V(empty)"],"skip":["不必写main框架"],"pitfalls":["P2/P3漏V(empty)致死锁"]},{"year":2009,"qno":46,"subject":"操作系统","type":"计算题（请求分页）","title":"带快表的请求分页访存时间","score":"（未标）","budgetMin":"12","detail":"页面大小 4KB，说明低 12 位是页内偏移，虚地址高位查页表；访问时间要按“快表命中、页表命中但快表未命中、缺页”三种情况分别累加。缺页那一路除访问内存取页表项外，还要加上磁盘 I/O 时间，并且换页后必须重新查一次快表，漏掉这 10ns 就会少算。最后把页框号与页内偏移拼接成物理地址，注意十六进制对位的写法。","kp":["请求分页","快表TLB","缺页处理","有效访问时间"],"answerKey":["页面4KB→低12位页内偏移","2362H：10+100+100=210ns","1565H：10+100+10^8+10+100=100000220ns","25A5H：10+100=110ns","1565H页框号101H→物理地址101565H"],"mustWrite":["三个地址的访问时间及算式","1565H物理地址101565H"],"skip":["不必复述页式管理原理"],"pitfalls":["缺页后漏重查快表（少10ns）"]},{"year":2009,"qno":47,"subject":"计算机网络","type":"应用题（CIDR/路由）","title":"子网划分、路由表与地址聚合","score":"（未标）","budgetMin":"12","detail":"这题把 CIDR 的三件事串在一起：先按所需主机数确定主机号位数，反推子网号位数并写出两个子网的网络地址与掩码；再为路由器填路由表，直连子网指向对应接口，DNS 服务器用主机路由（掩码全 1）指向下一跳；最后把两个子网聚合成一条 /24 路由发往 Internet，并补默认路由。结论要落在“网络/掩码/下一跳/接口”四元组上，默认路由别漏写 0.0.0.0/0；子网号全 0 全 1 在这里是可用的。","kp":["CIDR","子网划分","路由聚合","默认路由"],"answerKey":["主机号≥7位、子网号1位","子网202.118.1.0/25与202.118.1.128/25（两子网对应局域网1/2的两种分配均可）","掩码255.255.255.128；DNS项掩码全1、下一跳202.118.2.2","默认路由0.0.0.0/0；聚合202.118.1.0/24"],"mustWrite":["两个子网地址及掩码","路由表：网络/掩码/下一跳/接口","聚合202.118.1.0/24"],"skip":["别认为子网号不能全0全1"],"pitfalls":["默认路由漏0.0.0.0/0"]},{"year":2010,"qno":41,"subject":"数据结构","type":"应用题（散列表）","title":"线性探测散列表与查找长度","score":"（未标）","budgetMin":"10","detail":"先由装填因子 0.7 和 7 个关键字定出表长 10、地址 0~9，再按给定散列函数逐个插入，冲突时用线性探测找下一个空位。画表时要一个萝卜一个坑地标出每个关键字的最终地址，这是后面算查找长度的依据。两个平均查找长度分母不同：成功的按关键字个数 7 除，失败的按散列函数可能取到的地址数 7 除，而不是按表长 10 除——这是本题最大的陷阱。","kp":["散列表","线性探测","装填因子","ASL"],"answerKey":["装载因子0.7、7个数据→表长10，下标0~9","H(key)=(key×3) mod 7（7→0、8→3、30→6、11→5、18→5、9→6、14→0），线性探测再散列","散列表（线性探测）：0:7 1:14 2:空 3:8 4:空 5:11 6:30 7:18 8:9 9:空","ASL成功=(1+2+1+1+1+3+3)/7=12/7","ASL失败=(3+2+1+2+1+5+4)/7=18/7"],"mustWrite":["画出地址0~9的散列表","两个ASL的算式与结果"],"skip":["ASL失败不除表长10，应除7"],"pitfalls":["ASL失败按关键字而非H(key)位置算"]},{"year":2010,"qno":42,"subject":"数据结构","type":"算法设计题（数组）","title":"数组循环左移的三次逆置","score":"（未标）","budgetMin":"12","detail":"把长度为 n 的数组循环左移 p 位，等价于把前 p 个元素与后 n-p 个元素交换位置，可用三次逆置完成：先逆置前一段，再逆置后一段，最后整体逆置。要写清三个逆置区间的端点和先后顺序，区间端点错一位结果就全错；再给出 Reverse 与 Converse 的代码以及 O(n) 时间、O(1) 空间的结论。用辅助数组暂存前 p 个元素也能做对，但空间是 O(p)，属于次优解。","kp":["数组逆置","循环左移","原地算法","时间复杂度"],"answerKey":["思想：a逆置、b逆置、整体逆置即得ba","三次Reverse：(0,p-1)、(p,n-1)、(0,n-1)","时间O(n)，空间O(1)","另解：辅助数组暂存前p个，空间O(p)"],"mustWrite":["三次逆置的区间与顺序","Reverse与Converse的C代码","复杂度O(n)、O(1)"],"skip":["辅助数组另解亦可，空间为O(p)"],"pitfalls":["区间端点写错，移位结果不对"]},{"year":2010,"qno":43,"subject":"计算机组成原理","type":"计算题（指令格式）","title":"指令格式分析与机器码还原","score":"（未标）","budgetMin":"10","detail":"本题从指令字长出发逐字段反推：操作码 4 位决定最多 16 条指令，寄存器号 3 位决定 8 个通用寄存器；主存 128KB 按字（2B）编址，单元数 2^16，故 MAR、MDR 都是 16 位，地址范围 0000H~FFFFH。按字节编址去算 MAR 位数是最常见的失分点。后半问要把汇编指令组装成机器码，并模拟寄存器内容与存储单元的变化，注意自增型操作数先取后加。","kp":["指令格式","操作码","寄存器编号","编址方式"],"answerKey":["操作码4位→最多16条；寄存器号3位→8个通用寄存器","128KB按字(2B)编址→2^16单元，MAR、MDR均16位","目标地址范围0000H~FFFFH","add (R4),(R5)+机器码2315H","R5:5678H→5679H；(5678H)→68ACH"],"mustWrite":["地址范围0000H~FFFFH","机器码2315H","R5与5678H单元变化"],"skip":["不必推导全部指令编码"],"pitfalls":["按字节编址误算MAR位数"]},{"year":2010,"qno":44,"subject":"计算机组成原理","type":"计算题（Cache）","title":"Cache 标记位与程序命中率","score":"（未标）","budgetMin":"12","detail":"先由地址位数减去块内地址位数和行号位数得到标记位数，再逐项算控制位与总容量：每行除数据外还有有效位和标记位，容量公式别漏项。接着按数组元素地址推出它落在哪一行，判断两次访问是否落在同一行而发生替换。两个程序的差别在访问顺序，按行遍历时只有行首不命中，按列遍历则每次都不命中，命中率要靠数的而不是猜的。","kp":["Cache映射","标记位","命中率","直接映射"],"answerKey":["1位有效位+19位标记位；总容量8×(64+20/8)=532B","a[0][31]对应行号6；a[1][1]对应行号5","程序A命中率=15/16=93.75%","程序B逐列访问每次不命中，命中率0"],"mustWrite":["Tag=28-6-3=19位；容量532B","A、B命中率93.75%与0"],"skip":["控制位不计入容量计算"],"pitfalls":["Tag位数或容量公式写错"]},{"year":2010,"qno":45,"subject":"操作系统","type":"计算题（磁盘调度）","title":"位图容量与 CSCAN 磁盘调度","score":"（未标）","budgetMin":"12","detail":"前两问是容量与地址换算：磁盘块数除以每字的位数得到位图字数，再折算成字节，与内存可容纳量比较。后两问按 CSCAN 的规则算出磁头移动的总磁道数，乘以每磁道寻道时间得寻道总时间，再加上旋转延迟与传输时间；旋转延迟要按访问次数累加，漏乘次数是典型错误。最后一问换到 Flash，因为没有寻道和旋转延迟，调度算法应该选最简单的 FCFS。","kp":["位图","磁盘调度","CSCAN","寻道时间"],"answerKey":["位图：16384/32=512字=2KB，可放内存","CSCAN移动磁道20+90+20+40=170，寻道170ms","旋转延迟总20ms；读取扇区总0.4ms","总时间190.4ms","Flash宜用FCFS，无寻道与旋转"],"mustWrite":["位图2KB的算式","总时间190.4ms","FCFS及理由"],"skip":["不必比较各调度算法"],"pitfalls":["旋转延迟漏乘访问次数"]},{"year":2010,"qno":46,"subject":"操作系统","type":"计算题（分页置换）","title":"页式地址转换与 CLOCK 置换","score":"（未标）","budgetMin":"12","detail":"逻辑与物理空间都是 64KB，可推出页号与页内偏移各占的位数，再把十六进制逻辑地址拆成页号加偏移，查页表得页框号后拼出物理地址。置换部分要区分 FIFO 与 CLOCK：FIFO 淘汰最早装入的页，CLOCK 则从指针处扫描，遇到使用位为 1 的清零并跳过，遇到 0 才淘汰。CLOCK 不写“清使用位”这一步，指针位置就会算错，最后地址也对不上。","kp":["分页管理","逻辑地址转换","CLOCK算法","页面置换"],"answerKey":["逻辑/物理空间均64KB→页号6位+页内10位","17CAH页号000101B=5","置换最早装入的0号页，5号页装入7号框→物理地址1FCAH","CLOCK：2→4→7→9清使用位，第5次淘汰2号页，得0BCAH"],"mustWrite":["页号5、物理地址1FCAH","CLOCK顺序2→4→7→9→2及0BCAH"],"skip":["不必写页表项结构细节"],"pitfalls":["CLOCK漏清使用位"]},{"year":2010,"qno":47,"subject":"计算机网络","type":"计算题（CSMA/CD）","title":"CSMA/CD 争用期与有效速率","score":"（未标）","budgetMin":"12","detail":"冲突检测时间的两个极端来自发送双方的相对时机：最短是两端同时发送、只需单程传播时延就被检测到，最长是对方在数据即将到达时发送、要往返双程才检测到，所以最短为 τ、最长为 2τ，别把 2τ 当最短。总时间由建立链路、发送一帧和最后一次确认的时延拼接而成，有效速率则用有效数据量除以总时间，注意扣除帧头开销。","kp":["CSMA/CD","争用期","传播时延","有效传输速率"],"answerKey":["最短（甲乙同时发送）：τ=0.01ms（单程传播时延）","最长（乙在数据将到时发送）：2τ=0.02ms（双程传播时延）","发送时延t1=1518×8b/10Mbps≈1.21ms","T=t1+t2+2τ0=1.2856ms","有效速率1500×8/T≈9.33Mbps"],"mustWrite":["最短0.01ms与最长0.02ms","T=1.2856ms、速率≈9.33Mbps"],"skip":["不必推导CSMA/CD原理"],"pitfalls":["把双程时延当最短检测时间"]},{"year":2011,"qno":41,"subject":"数据结构","type":"应用题（关键路径）","title":"压缩存储还原图与关键路径","score":"（未标）","budgetMin":"12","detail":"第一问是从上三角的压缩存储倒推出邻接矩阵：按各行上三角元素个数依次取出权值，填到对应位置，其余置 0，再据此画出有向带权图。第二问按拓扑顺序求各顶点最早发生时间 ve，逆拓扑顺序求最迟发生时间 vl，再由活动的最早开始与最迟开始之差判定关键活动。注意汇点的 ve 与 vl 相等，且 ve 要取所有前驱路径的最大值，漏算某条入边会让关键路径判断全错。","kp":["关键路径","邻接矩阵","压缩存储","最早最迟时间"],"answerKey":["由压缩存储（各行上三角元素数5,4,3,2,1）还原邻接矩阵A：a0-1=4、a0-2=6、a1-2=5、a2-3=4、a2-4=3、a3-5=3、a4-5=3，其余为0","由邻接矩阵画有向带权图G","ve=0,4,9,13,12,16；vl=0,4,9,13,13,16","l-e：a0-2为3，a2-4、a4-5各为1，其余为0","关键路径a0-1、a1-2、a2-3、a3-5，长度4+5+4+3=16"],"mustWrite":["ve与vl两组各6个值","关键路径四段及总长16"],"skip":["不必逐步抄写max/min过程"],"pitfalls":["漏算ve(4)=12，关键路径判断出错"]},{"year":2011,"qno":42,"subject":"数据结构","type":"算法设计题（中位数）","title":"两个等长有序序列的中位数","score":"（未标）","budgetMin":"15","detail":"要求 O(log n) 时间求两个等长升序序列的中位数，做法是分治折半：分别取两序列的中位数比较，相等即得答案；不等时保留较大中位数所在序列的前半段与较小中位数所在序列的后半段，且丢弃的元素个数必须相等，保证剩下的仍是等长序列。反复直到各剩一个元素，取较小者即中位数。用归并或辅助数组只能拿部分分，奇偶长度处理不一致、丢弃长度不等是常见错误。","kp":["中位数","分治","折半","时间复杂度"],"answerKey":["分别取A、B中位数a、b；a=b则a即中位数","a<b弃A较小一半、B较大一半，长度相等，反之对称","重复至各剩1个元素，取较小者","时间O(log2 n)，空间O(1)"],"mustWrite":["三种情况下的舍弃规则（长度相等）","返回较小者；复杂度O(log2 n)/O(1)"],"skip":["别归并排序求中位数（只得部分分）","别用辅助数组"],"pitfalls":["奇偶长度处理不一致，丢弃长度不等"]},{"year":2011,"qno":43,"subject":"计算机组成原理","type":"计算分析题（补码加减）","title":"补码加减运算与溢出判断","score":"（未标）","budgetMin":"12","detail":"先把两个十进制数写成 8 位补码，再分别做减法和加法，结果为负时要写成补码形式并还原成真值。核心结论是：无符号数的加法与补码加减可以用同一个加法器实现，差别只在是否看符号位和如何判溢出。溢出判断记两条等价规则——两加数同号而结果异号，或次高位进位与最高位进位不同；本题最后一句运算结果就是溢出的情形，务必点明。","kp":["补码","溢出判断","符号位","加法器"],"answerKey":["x=134→10000110B=86H","y=246→11110110B","x-y=90H；x+y=7CH（有进位）","m同x=86H，补码为-122；x-y结果90H为-112","能：无符号、补码加减均可用一个加法器实现","溢出判断：两加数同号而结果异号（或次高位进位≠最高位进位）；最后一句溢出"],"mustWrite":["86H、90H、7CH三个结果","溢出判断规则并指出溢出"],"skip":["不必证明补码运算公式"],"pitfalls":["用无符号值判断符号位"]},{"year":2011,"qno":44,"subject":"计算机组成原理","type":"计算题（虚存+Cache）","title":"虚地址到 Cache 的命中判断","score":"（未标）","budgetMin":"12","detail":"先由虚地址与物理地址位数差确定页内偏移、虚页号与页框号位数，再按 Cache 的行数、块大小拆出块内地址、行号和标记字段。判断是否命中要两步都走通：先查 TLB 或页表把虚地址转成物理地址，再用物理地址的行号与标记去比对 Cache 行。TLB 的多路组相联还要先算组数、组号和标记位数，命中判断漏比标记位是本题最常见的失分点。","kp":["虚拟存储","页表","TLB","Cache映射"],"answerKey":["虚地址24位、物理20位；页内12位，虚页号12、页框号8位","Cache：块内5位、行号3位、标记12位","001C60H→物理04C60H；标记105H≠04CH，不命中","TLB 4路→2组，标记11位、组号1位；024BACH标志012H、组0，命中"],"mustWrite":["地址字段划分12+12/8+12/5+3+12","04C60H不命中、024BACH命中"],"skip":["不必写页表项结构"],"pitfalls":["命中判断漏比标记位"]},{"year":2011,"qno":45,"subject":"操作系统","type":"PV操作题","title":"银行叫号系统的 PV 同步","score":"（未标）","budgetMin":"10","detail":"这是有容量限制的同步问题：空座位数是资源，已占座数是要服务的对象，叫号是营业员对顾客的唤醒。要设互斥信号量保护取号机，再用空座位、已占座、叫号三个同步信号量刻画流程，初值分别对应容量、0 和 0。顾客的顺序是“先 P 空座位、再 P 互斥取号、V 互斥、V 已占座、P 叫号”，营业员反过来“P 已占座、V 空座位、V 叫号”后服务；顾客若误用 P(已占座) 会自己把自己锁死。","kp":["PV操作","信号量","同步与互斥","生产者消费者"],"answerKey":["互斥：取号机用mutex=1","同步：empty=10（空座位）、full=0（已占座）、service=0（叫号）","顾客：P(empty),P(mutex)取号,V(mutex),V(full),P(service)","营业员：P(full),V(empty),V(service)后服务"],"mustWrite":["四个信号量名与初值","顾客/营业员的P、V顺序"],"skip":["不必写座位号等细节"],"pitfalls":["顾客误用P(full)自锁"]},{"year":2011,"qno":46,"subject":"操作系统","type":"简答题（文件物理结构）","title":"连续结构选型与 FCB 设计","score":"（未标）","budgetMin":"10","detail":"题目问视频文件适合哪种物理结构，答案是连续分配：磁道相邻、寻道距离短，支持随机访问且效率最高。为此 FCB 里要保存起始块号和块数（或结束块号），这是能直接定位文件的必要信息，只答结构不写字段会丢分。最后要说明把 FCB 集中存放、文件数据集中存放的好处：按名检索时只需读 FCB 所在的少数盘块，减少磁头移动和 I/O 次数。","kp":["文件物理结构","连续分配","FCB","目录检索"],"answerKey":["宜用连续结构：寻道短、随机访问效率高","FCB加字段：<起始块号,块数>或<起始块号,结束块号>","FCB集中存放、数据集中存放，随机查名只访问FCB块，减少磁头移动与I/O"],"mustWrite":["连续结构及两个FCB字段","FCB集中存放的理由"],"skip":["不必比较三种物理结构"],"pitfalls":["只答结构不写FCB字段"]},{"year":2011,"qno":47,"subject":"计算机网络","type":"应用题（帧/IP/ARP/NAT）","title":"ARP 与 NAT 的以太帧转换","score":"（未标）","budgetMin":"12","detail":"先由域名解析结果写出目的 IP 的点分十进制形式，再判断以太网帧首部的目的 MAC：跨网段时填的是默认网关的 MAC，而不是最终目的主机的 MAC。ARP 请求是广播帧，目的 MAC 全 1。HTTP/1.1 非流水方式下，取回一个对象要先建连接再请求，总时延按 RTT 个数累加。NAT 转换只改源 IP（必要时改源端口），路由器转发时 TTL 减 1 并重新计算首部校验和。","kp":["以太网帧","ARP","NAT","RTT"],"answerKey":["目的IP十进制64.170.98.32","帧首6字节即网关MAC","ARP请求目的MAC全1：FF-FF-FF-FF-FF-FF","HTTP/1.1非流水：1+5=6个RTT","NAT：源IP改101.12.123.15，TTL减1、校验和重算"],"mustWrite":["目的IP 64.170.98.32","6个RTT；源IP改101.12.123.15"],"skip":["罗列IP头字段不给分"],"pitfalls":["把帧前4bit字节计数当内容"]},{"year":2012,"qno":41,"subject":"数据结构","type":"简答/计算","title":"最佳归并树的合并次数","score":"（未标）","budgetMin":"12","detail":"考的是多路归并的最优合并次序：把各表长度当作叶结点权值，每次挑最短的两张表合并，得到的合并过程就是最佳归并树（哈夫曼树）。合并两张长表的最坏比较次数等于两表长之和减 1，按这个顺序依次累加即得总比较次数 825。考场上先把表长排序，再把每次合并产生的新表放回待合并集合，别漏掉新生成的表。","kp":["最佳归并树","哈夫曼树","归并排序","表合并"],"answerKey":["6 表长 10/35/40/50/60/200","合并得 45、85、110、195、395","次数 44+84+109+194+394=825","策略：每次合并最短两表（最佳归并树）"],"mustWrite":["每次合并最坏比较=两表长之和−1","总次数 825","策略写“类似哈夫曼树/最佳归并树”"],"skip":["不用写各表内部排序","不用写一般化公式"],"pitfalls":["只给过程不给 825（丢 2 分）","任意合并只得 3 分档"]},{"year":2012,"qno":42,"subject":"数据结构","type":"算法题","title":"链表共同后缀起始结点","score":"13分","budgetMin":"14","detail":"求两个链表的共同后缀起始位置，关键是两表长度不同，必须先把尾端对齐。先分别求出 len1、len2，让长表先走 |len1−len2| 步，再让 p、q 同步后移，当 p->next == q->next 时该 next 就是共同后缀的起点。返回值是 p->next 而不是 p，因为比较的是下一个结点是否为同一个；整体时间 O(len1+len2)、空间 O(1)。","kp":["单链表","双指针","链表长度","公共后缀"],"answerKey":["求两表长 len1、len2","长表先走 |len1−len2| 步对齐表尾","p、q 同步后移，next 相等即起点","返回 p->next"],"mustWrite":["设计思想：长度差对齐后同步遍历","代码：两次 for 对齐+while 比较","时间 O(len1+len2)"],"skip":["不用写求交集/公共元素","不用写哈希表解法（双指针 O(len1+len2) 即可满分）"],"pitfalls":["只比 p、q 不比 next，错一结点","O(len1×len2) 扣至 9 分"]},{"year":2012,"qno":43,"subject":"计算机组成原理","type":"计算题","title":"Cache缺失与DMA带宽","score":"10分","budgetMin":"12","detail":"先用主频与 CPI 求 MIPS 和指令条数，乘缺失率得每秒缺失次数，再乘缺失块大小就得到主存带宽的下限 4.8MB/s。缺页也要折算成 DMA 次数：每秒缺页数乘页大小再除以每次 DMA 传送的字节数，得 1536 次/s。DMA 与 CPU 争用总线时 DMA 优先，否则数据会丢失；四体交叉存储的带宽别忘了乘体数 4。","kp":["Cache缺失率","DMA","存储器带宽","多体交叉存储"],"answerKey":["MIPS=80M/4=20","缺失 20M×1.5×1%=300k","带宽≥16B×300k=4.8MB/s","缺页 1.5/s→DMA 1.5×4KB/4B=1536 次/s","DMA 优先；四体 4×4B/50ns=320MB/s"],"mustWrite":["4.8MB/s、1536 次/s、320MB/s 带单位","DMA 优先的理由（数据丢失）"],"skip":["不用写 cache 替换策略"],"pitfalls":["漏单位；DMA 按字节算","四体带宽忘乘 4"]},{"year":2012,"qno":44,"subject":"计算机组成原理","type":"综合题","title":"补码右移与流水线阻塞","score":"（未标）","budgetMin":"12","detail":"补码做算术右移时高位要补符号位：FDFFH 最高位为 1，右移一位得 FEFFH；若按逻辑右移会得到 7EFFH，是典型错解。流水线部分要抓数据相关：I3 在 ID 段需要上一条指令的结果，按序发射导致 I3 阻塞，I4 的 IF 也随之后推。把 x=x*2+a 的 5 条指令按这个规则逐段排开，共 17 个时钟周期，不要按无阻塞的 9 周期作答。","kp":["算术右移","补码","数据相关","指令流水线"],"answerKey":["x 补码 FDFFH，算术右移 1 位→FEFFH","4+(5−1)=8 个时钟周期","I3 的 ID 因数据相关阻塞，I4 的 IF 随之阻塞","x=x*2+a 5 条指令共 17 周期"],"mustWrite":["FDFFH→FEFFH","17 个时钟周期","阻塞写“数据相关”+“按序发射”"],"skip":["不用写流水段电路"],"pitfalls":["逻辑右移得 7EFFH（错）","按无阻塞 9 周期答"]},{"year":2012,"qno":45,"subject":"操作系统","type":"简答题","title":"空闲页框分配与局部性","score":"（未标）","budgetMin":"8","detail":"本题考空闲页框链表的分配策略：一般从链表头摘取页框，而对被换出后又被重新访问的页面，可以把它原来占用的页框重新分配回去，从没访问过的页面则按链表顺序取。这样做是合适的——页面时间局部性越强，取回旧页框后再次命中的概率越大，能省下一次读盘。答题要逐条给出页框号并写明选择依据，只给号码不写理由会丢分。","kp":["页框分配","空闲链表","时间局部性","请求调页"],"answerKey":["0 页→空闲链表第 3 个页框 21","1 页被重新访问→取回页框 32","2 页从未访问→取链表头页框 41","合适：时间局部性越好，取回机会越大"],"mustWrite":["三个页框号 21/32/41 各带理由","结论“合适”+局部性理由"],"skip":["不用写置换算法通式"],"pitfalls":["只给页框号不写理由"]},{"year":2012,"qno":46,"subject":"操作系统","type":"计算题","title":"文件索引结点寻址范围","score":"（未标）","budgetMin":"10","detail":"先把块号位数算出来：4TB÷1KB=2^32 块，所以块号至少 32 位即 4B，这是后面所有推算的基础。512B 的索引区按 4B 一项可放 128 项，可覆盖 128×1KB=128KB；再结合连续分配方案里起始块号与块数各占 4B 的编码上限，可推出 2^26B+84KB 一类的长度。整条链条是「地址位数→可寻址块数→乘块大小」，索引项大小最容易算错。","kp":["索引结点","文件寻址","磁盘块号","文件最大长度"],"answerKey":["4TB/1KB=2^32 块→块号 32 位=4B","512B/4B=128 项→最大 128KB","连续 2^16 块=2^26B；504/6=84 项→2^26B+84KB","最大化：起始块号、块数各 4B，共 4TB"],"mustWrite":["块号 4B 的推导（32/8）","128KB 与 2^26B+84KB 两个结论"],"skip":["不用写三级间接索引"],"pitfalls":["索引项按 4B 算→84 项错","漏“块号最少 4B”推理"]},{"year":2012,"qno":47,"subject":"计算机网络","type":"分析题","title":"以太网帧与三次握手分析","score":"（未标）","budgetMin":"10","detail":"先按以太网帧首部长度定位 IP 首部，源 IP 地址固定在第 13–16 字节，据此就能判断哪些帧由主机 H 发出；再结合序号字段确认 1、2、3 号帧完成的是 TCP 三次握手。以太网规定最小载荷 46 字节，总长不足必须填充，所以总长 40 字节的帧要补到 46，不要把 40 字节当成载荷长度。判断依据要写清「源 IP 在 13–16 字节」，而不是只给结论。","kp":["以太网帧","最小帧长","TCP三次握手","IP首部"],"answerKey":["源 IP 在第 13–16 字节；1、3、4 号=192.168.0.8 由 H 发","1、2、3 号完成三次握手","3、5 号总长 40(28H)<46 字节→需填充","第(2)问源文本残缺，止于“S 已经收到的应用层数据的字节数”，答案缺失"],"mustWrite":["判断依据写“源 IP 在 13–16 字节”","填充+46 字节最小载荷"],"skip":["不用写 47-a 表逐字段解析"],"pitfalls":["把 40 字节当载荷"]},{"year":2013,"qno":41,"subject":"数据结构","type":"算法题","title":"主元素的摩尔投票法","score":"13分","budgetMin":"15","detail":"求出现次数超过 n/2 的主元素，标准解法是两遍扫描的摩尔投票：第一遍计数为 0 时换候选并置 1，与候选相同加 1、不同减 1；第二遍统计该候选的真实出现次数，大于 n/2 才返回它，否则返回 −1。只选候选不做二次确认，会把只出现一次的众数误判成主元素，这是最常见的丢分点。全程 O(n) 时间、O(1) 空间，先排序再统计只能拿 11 分。","kp":["主元素","摩尔投票","数组遍历","O(n)算法"],"answerKey":["候选：计数 0 时换候选并置 1，同则 +1、异则 −1","二次扫描 count>n/2 返回该值，否则 −1","时间 O(n)、空间 O(1)"],"mustWrite":["两步设计思想：选候选+计数确认","代码含抵消计数与二次统计","O(n)/O(1)"],"skip":["不用写先排序再统计（最高 11 分）","不用写数学证明"],"pitfalls":["只选候选不二次确认（1,2,3 误判）","把众数当主元素"]},{"year":2013,"qno":42,"subject":"数据结构","type":"简答/计算","title":"按概率降序的顺序查找","score":"（未标）","budgetMin":"8","detail":"折半查找的前提是元素有序且顺序存储，但各元素查找概率不等时它不再最优：把元素按概率降序排列后做顺序查找，ASL 最小，为 0.35×1+0.35×2+0.15×3+0.15×4=2.1。链式存储不能随机访问，只能顺序查找，ASL 同样是 2.1；若改按概率构造二叉排序树，ASL 可降到 2.0。关键是先按概率降序重排再算 ASL，顺序搞错结论全错。","kp":["折半查找","顺序查找","平均查找长度ASL","存储结构"],"answerKey":["折半查找要求元素有序且顺序存储；各元素概率不等时折半不一定优于顺序查找，按概率降序排列+顺序查找 ASL 最小","ASL=0.35×1+0.35×2+0.15×3+0.15×4=2.1","链式只能顺序查找（同 2.1）；或按概率建 BST，ASL=2.0"],"mustWrite":["降序排列+顺序查找+ASL 2.1","链式存储下的对应方案"],"skip":["不用写折半判定树全图"],"pitfalls":["概率未降序→ASL 错"]},{"year":2013,"qno":43,"subject":"计算机组成原理","type":"计算题","title":"总线带宽与访存时间计算","score":"（未标）","budgetMin":"10","detail":"先由主频求 CPU 周期 1/800MHz=1.25ns，总线周期为 5ns，再用一次总线传送 4B 乘总线频率 200MHz 得带宽 800MB/s。一次访存时间由总线周期与存储器访问时间构成：5ns+40ns+8×5ns=85ns。整段执行时间要把命中与缺失分开：命中 500ns，缺失部分用访存次数×缺失率×单次缺失开销，合计 1010ns。带宽忘乘频率、缺失开销漏乘缺失率是两处高频错误。","kp":["总线带宽","总线周期","Cache缺失","访存时间"],"answerKey":["CPU 周期 1/800MHz=1.25ns；总线周期 5ns","带宽 4B×200MHz=800MB/s","5ns+40ns+8×5ns=85ns","命中 500ns，缺失 1.2×100×5%×85=510ns，共 1010ns"],"mustWrite":["800MB/s、85ns、1010ns 带单位","执行时间=命中+缺失开销"],"skip":["不用写总线握手时序"],"pitfalls":["带宽忘乘频率","缺失开销漏 CPI/缺失率"]},{"year":2013,"qno":44,"subject":"计算机组成原理","type":"综合题","title":"相对寻址跳转与标志位","score":"（未标）","budgetMin":"12","detail":"先由「下条指令地址=(PC)+2」判断按字节编址、指令长 16 位；OFFSET 是 8 位补码，范围 −128~127，向后最多跳 127 条指令，目标地址按 PC+2+OFFSET×2 计算，E3H 对应 FFC6H，目标为 1FD4H，不转移则 PC=200EH。带符号数比较只看 CF、ZF，所以第 3 问应置 C=Z=1、N=0，不能把 NF 用在无符号比较上。第三小问的三个部件依次是指令寄存器、移位寄存器、加法器；OFFSET 忘了乘 2 会全盘算错。","kp":["PC相对寻址","指令格式","标志位","补码偏移"],"answerKey":["指令 16 位、下条 (PC)+2→按字节编址","OFFSET 8 位补码 −128~127，向后最多可跳转 127 条指令","CF=0,ZF=0,NF=1 转移；E3H→FFC6H→目标 1FD4H","不转移 PC=200EH","第 3 问：C、Z、N 应分别置 C=Z=1、N=0（只测 CF、ZF，不测 NF）","①指令寄存器 ②移位寄存器 ③加法器"],"mustWrite":["1FD4H 与 200EH","−128~127（最多 127 条）","三个部件名","C=Z=1、N=0"],"skip":["不用写标志位电路"],"pitfalls":["OFFSET 忘乘 2","把 NF 用于无符号比较"]},{"year":2013,"qno":45,"subject":"操作系统","type":"信号量","title":"博物馆人数控制信号量","score":"7分","budgetMin":"8","detail":"博物馆容量 500，需要两个信号量：empty 初值 500 控制馆内人数，mutex 初值 1 保护过门的临界区。进门时先 P(empty) 判断是否满员，再 P(mutex)/V(mutex) 完成一次过门；出馆时先过临界区再 V(empty)。empty 必须「进 P 出 V」严格配对，配对写反会导致人数统计错误；mutex 只包住判断与通过这一段临界区，不能包住整个参观过程，否则会退化成串行。","kp":["PV操作","信号量","互斥","同步"],"answerKey":["mutex=1 控出入口互斥；empty=500 控馆内人数","进门：P(empty)→P(mutex)/V(mutex)","出门：P(mutex)/V(mutex)→V(empty)"],"mustWrite":["两信号量初值与含义（4 分）","empty 进 P 出 V 配对","mutex 只包过门临界区"],"skip":["不用写参观者计数变量"],"pitfalls":["V(empty) 写到进门处","漏 mutex 致同时过门"]},{"year":2013,"qno":46,"subject":"操作系统","type":"计算题","title":"两级页表地址变换计算","score":"8分","budgetMin":"12","detail":"先由页内偏移 12 位得页大小 4KB，页目录项与页表项各 4B，页表项总数 2^20 项，故页表占 2^20×4B=4MB。地址变换要会写位运算：页目录号 =(LA>>22)&0x3FF，页表索引 = LA>>12。给定页目录基址时，第 8 项的地址是 00200000H+8×4=00200020H，读出内容 00900H 得物理地址 900000H；00200024H 同理得 901000H。偏移位数和最后那个「加 8×4」都是常见丢分点。","kp":["两级页表","页目录","地址变换","物理地址"],"answerKey":["偏移 12 位→页 4KB；2^20×4B=4MB","页目录号 (LA>>22)&0x3FF；索引 >>12","第 8 项物理地址 00200000H+8×4=00200020H","00200020H=00900H→900000H；00200024H=00901H→901000H"],"mustWrite":["4KB、4MB","两个位运算表达式","00200020H 与页框 900/901"],"skip":["不用写变换流程文字"],"pitfalls":["偏移位数算错","物理地址忘加 8×4"]},{"year":2013,"qno":47,"subject":"计算机网络","type":"综合题","title":"路由聚合与最长前缀匹配","score":"9分","budgetMin":"12","detail":"按最长前缀匹配填路由表：把 153.14.5.0/25 与 153.14.5.128/25 聚合成 /24，下一跳 153.14.3.2、接口 S0；194.17.20.0/25 与 194.17.21.0/24 聚合成 /23，下一跳 194.17.24.2、接口 S1；194.17.20.128/25 是直连，下一跳写「—」、接口 E0。第 (2) 问按最长匹配应选 E0，不要误写成聚合项。不同 AS 之间交换路由信息用 BGP，它封装在 TCP 之上。","kp":["路由聚合","最长前缀匹配","BGP","路由表"],"answerKey":["153.14.5.0/25+.128/25→/24，153.14.3.2，S0","194.17.20.0/25+194.17.21.0/24→/23，194.17.24.2，S1","194.17.20.128/25 直连 —，E0","(2) 最长匹配→E0","不同 AS→BGP，封在 TCP"],"mustWrite":["三条路由项：网段+前缀+下一跳+接口","最长匹配→E0","BGP 用 TCP"],"skip":["不用写路由收敛"],"pitfalls":["第 3 条误写成聚合"]},{"year":2014,"qno":41,"subject":"数据结构","type":"算法题","title":"二叉树的带权路径长度","score":"（未标）","budgetMin":"15","detail":"求二叉树的带权路径长度 WPL，就是所有叶结点的深度乘权值之和。最直观的做法是先序递归，把当前深度当参数往下传，遇到左右孩子都为空的叶结点就累加 deep×weight；也可以用层次遍历记录层号与 lastNode。注意根结点的深度按题设从 1 起算，传 0 会让每个叶结点少算一层、WPL 全错；叶判断必须左右两个指针都为空。时间 O(n)，递归栈空间 O(h)。","kp":["WPL","先序遍历","二叉树","递归"],"answerKey":["先序递归：深度作参数，叶结点累加 deep×weight","或层次遍历：记层号与 lastNode","类型定义含 int weight 与左右孩子指针","时间 O(n)，空间 O(h)/O(n)"],"mustWrite":["设计思想含深度参数","代码含双 NULL 叶判断","O(n) 复杂度"],"skip":["不用写非递归先序","不用写 static 原理"],"pitfalls":["根深度传 0→WPL 错","叶判断漏判一个孩子"]},{"year":2014,"qno":42,"subject":"数据结构","type":"综合题","title":"路由图邻接表与最短路","score":"10分","budgetMin":"15","detail":"本题是数据结构题，要求用图的链式存储描述网络拓扑：表头结点存 RouterID 与弧指针，弧用 Flag 区分 Link（相邻路由器）与 Net（含 Prefix、Mask），共 8 个表头结点，两类弧可用 union 共用存储。建好图后用最短路逐一推代价：192.1.1.0/24 直接到达代价 1，192.1.5.0/24 经 R1→R3 代价 3，192.1.6.0/24 经 R1→R2 代价 4，192.1.7.0/24 经 R1→R2→R4 代价 8。别把它当网络题去写 OSPF 报文。","kp":["邻接表","图存储","最短路径","无向图"],"answerKey":["表头 RouterID+弧指针；Flag=1 Link,2 Net(Prefix,Mask)","8 个表头结点+union 存两类弧","最短路：192.1.1.0/24 直接到达代价 1；192.1.5.0/24 经 R1→R3 代价 3；192.1.6.0/24 经 R1→R2 代价 4；192.1.7.0/24 经 R1→R2→R4 代价 8"],"mustWrite":["图（无向图）+邻接表式链式存储","Flag 区分两类弧的类型定义","四网段路径与代价"],"skip":["不用写 OSPF 报文"],"pitfalls":["当网络题写协议"]},{"year":2014,"qno":43,"subject":"计算机网络","type":"综合题","title":"CIDR聚合与TTL计算","score":"9分","budgetMin":"10","detail":"先把能聚合的网段合并：192.1.6.0/24 与 192.1.7.0/24 聚合成 192.1.6.0/23，于是路由表只需三条——192.1.1.0/24 走 E0，/23 走 10.1.1.2 的 L0，/24 走 10.1.1.10 的 L1。转发时按最长前缀匹配应选 L0，转发前 TTL 减 1，从 64 出发经过 3 跳后为 61。若要求 LSI 只发一条路由，配默认路由 0.0.0.0/0 且 Metric 10 即可。忘了聚合会让表项多于三条，TTL 也容易减错。","kp":["CIDR","路由聚合","TTL","默认路由"],"answerKey":["192.1.6.0/24+192.1.7.0/24→192.1.6.0/23","表：192.1.1.0/24 — E0；/23 10.1.1.2 L0；/24 10.1.1.10 L1","经 L0 转发，TTL=64−3=61","LSI 加 0.0.0.0/0，Metric 10"],"mustWrite":["三条路由项含下一跳与接口","TTL=61","0.0.0.0/0+Metric 10"],"skip":["不用写匹配比对"],"pitfalls":["忘聚合→多于 3 条","TTL 减错"]},{"year":2014,"qno":44,"subject":"计算机组成原理","type":"综合题","title":"相对寻址与流水线阻塞","score":"12分","budgetMin":"12","detail":"先用「32 位定长=4B、相邻指令地址差 4」判断按字节编址，再由左移两位即乘 4 得出元素占 4B。转移目标按 PC+4+OFFSET×4 计算，OFFSET=FFFAH 是 −6 的补码，一定要乘 4 才是字节偏移。流水线部分要逐条判断：第 2、3、4、6 条存在数据相关而阻塞，第 6 条属于控制冒险；第 5 条与下一次循环第 1 条的相关被第 6 条之后的 3 个时钟周期掩盖。不要把第 1、5 条算成阻塞。","kp":["相对寻址","数据相关","控制冒险","指令流水线"],"answerKey":["32 位定长=4B，地址差 4→按字节编址","左移两位即 ×4→元素 4B","OFFSET=FFFAH=−6；目标=PC+4+OFFSET×4","数据相关阻塞：第 2、3、4、6 条；第 6 条控制冒险","第 5 条与下次循环第 1 条的数据相关被第 6 条后的 3 个时钟周期阻塞消除（1 分）"],"mustWrite":["按字节编址的理由","OFFSET=−6 与跳转公式","第 2、3、4、6 条+第 6 条控制冒险"],"skip":["不用写各指令功能"],"pitfalls":["OFFSET 不乘 4","把第 1、5 条算阻塞"]},{"year":2014,"qno":45,"subject":"计算机组成原理","type":"综合题","title":"循环程序的Cache与TLB","score":"11分","budgetMin":"12","detail":"循环变量 i 累加到 1000 才跳出，所以寄存器终值是 1000。Cache 共 16×32B=512B，每个元素占 24B，落在同一块内的访问只缺失一次，命中率高达 99.98%，不能直接用 1000/6000 去算。执行过程中指令 4 可能溢出，指令 3 的地址可能缺页，所以要计一次访盘；TLB 访问次数要把 A[0] 也算进去共 1001 次，答 1000 会丢分。","kp":["Cache命中率","TLB","缺页","溢出"],"answerKey":["i 到 1000 跳出→寄存器 1000","cache 16×32B=512B","24B 同块→仅缺 1 次，命中率 99.98%","指令 4 可溢出；指令 3 可能缺页","访盘 1 次；TLB 1001 次"],"mustWrite":["99.98% 及“只缺失 1 次”理由","指令 4 溢出、指令 3 缺页","访盘 1 次、TLB 1001 次"],"skip":["不用写地址划分"],"pitfalls":["命中率按 1000/6000 算","TLB 答 1000（漏 A[0]）"]},{"year":2014,"qno":46,"subject":"操作系统","type":"计算题","title":"顺序与链接分配插入开销","score":"（未标）","budgetMin":"10","detail":"比较两种物理结构下插入记录的代价。顺序分配要把第 30 条之前的记录整体后移，每条记录读出、存回各算一次，前 29 条共 58 次，加存新记录 1 次得 59 次，同时 FCB 的起始块号与文件长度都要改。链接分配只需查第 29 块 29 次、写新块 1 次、改指针 1 次，共 31 次。第三问由 4B 地址推出 2^32 块，乘每个数据块的 1020B 得 4080GB，按 4096GB 算只能拿 1 分。","kp":["文件分配方式","顺序分配","链接分配","磁盘访问次数"],"answerKey":["顺序分配：前 29 条记录前移（每条读出、存回各 1 次，共 58 次）+存第 30 条 1 次=59 次；FCB 起始块号与文件长度改变","链接分配：查第 29 块 29 次+写新块 1+改指针 1=31 次","4B 地址→2^32 块×1020B=4080GB"],"mustWrite":["59 次（读、写各算一次）","31 次","4080GB（数据区 1020B）","FCB 起始块号与文件长度改变"],"skip":["不用写索引分配对比"],"pitfalls":["记录移动只算 1 次→得 30","按 4096GB 算只给 1 分"]},{"year":2014,"qno":47,"subject":"操作系统","type":"信号量","title":"每次取十个的生产者消费者","score":"8分","budgetMin":"10","detail":"缓冲区共享题需要四个信号量：empty=n、full=0 控制产品数量，mutex2 保护单次放入，mutex1 控制连续取 10 次的整体互斥。生产者执行 P(empty)、P(mutex2) 后放入，再 V(mutex2)、V(full)。消费者的 P(mutex1) 与 V(mutex1) 必须包住整个取十次的 for 循环，不能放进循环体内，否则取件过程会被其他进程插入。四个信号量的初值与含义都要写明，只背经典模板最多得 3 分。","kp":["PV操作","生产者消费者","信号量","临界区"],"answerKey":["mutex1=1 控连取 10 次；mutex2=1 控单次；empty=n；full=0","生产者 P(empty),P(mutex2) 放，V(mutex2),V(full)","消费者 P(mutex1) 包 for×10，再 V(mutex1)"],"mustWrite":["四信号量初值与含义","P(mutex1) 包 for 循环","empty=n、full=0"],"skip":["不用写经典模板（最多 3 分）"],"pitfalls":["mutex1 放 for 内"]},{"year":2015,"qno":41,"subject":"数据结构","type":"算法设计题","title":"链表删除绝对值重复结点","score":"（未标）","budgetMin":"15","detail":"这题考单链表的遍历去重，判定规则是“首次出现保留、再次出现删除”，而且数据绝对值不超过 n、结点数也是 n，于是可以用下标直接寻址的辅助数组代替哈希表。扫描时先看 q[|data|]：为 0 说明第一次见到，保留并把标记置 1；否则就是重复，用前驱指针做标准删除。考场先讲清辅助数组的大小与初值，再写指针操作，最后补时间 O(n)、空间 O(n) 的结论，得分点基本就在这三处。","kp":["单链表","辅助数组","空间换时间"],"answerKey":["辅助数组q[n+1]记已出现值（空间换时间）","一趟扫描：q[|data|]为0则保留并置1，否则删结点","时间O(n)、空间O(n)"],"mustWrite":["辅助数组大小n+1、初值0","保留首次出现、删重复","时间O(n)、空间O(n)"],"skip":["不写完整可编译代码与头文件","不逐行注释指针操作"],"pitfalls":["空间复杂度漏写","用双重循环→O(n²)"]},{"year":2015,"qno":42,"subject":"数据结构","type":"图计算题","title":"邻接矩阵幂与路径条数","score":"（未标）","budgetMin":"8","detail":"这题考邻接矩阵幂的语义：A 只刻画直接相连，而 A² 的每个元素表示长度恰为 2 的路径条数，不能把 A² 再按 A 的含义解释。算出第 0 行第 3 列为 3，就说明顶点 0 到 3 之间长度为 2 的路径有 3 条，再把结论推广为 B^m 的 i 行 j 列非零元＝i 到 j 长度为 m 的路径条数。考场不必抄整个矩阵与乘法过程，写出该元素的值，外加含“顶点对、长度、路径条数”三要素的结论句即可。","kp":["邻接矩阵","路径条数","矩阵乘法"],"answerKey":["A为5×5邻接矩阵（0/1）","A²第0行第3列=3：顶点0→3长度为2的路径3条","B^m(2≤m≤n)的i行j列非零元＝i→j长度为m的路径条数"],"mustWrite":["写出A²该元素值为3","结论句含“顶点i→j”“长度m”“路径条数”"],"skip":["不抄整个矩阵","不写矩阵乘法过程"],"pitfalls":["把A²含义当成A的含义","只写3条不写顶点对与长度"]},{"year":2015,"qno":43,"subject":"计算机组成原理","type":"数据通路分析题","title":"单总线数据通路与控制信号","score":"（未标）","budgetMin":"12","detail":"这题给的是单总线结构的数据通路，要回答哪些是可见寄存器、T 为什么存在、ALUop 与 SRop 各几位、SRout 起什么作用、各端口接到控制部件的哪些线。核心理解是单总线一拍只能传一个数据，A 口数据先暂存到 T，两端才不会同时读到同一个值；ALUop 三位对应 8 种运算、SRop 两位对应移位器四种功能，SRout 用三态门控制移位器是否驱动总线。考场先圈出寄存器与端口编号，再逐条写位数和连线，编号错了会整片失分。","kp":["数据通路","控制信号","暂存寄存器","ALU"],"answerKey":["可见寄存器R0~R3与PC","T暂存A口数据（单总线两端会同值）","ALUop 3位、SRop 2位","SRout控三态门，控制移位器与总线通断","①②③⑤⑧接控制部件；⑥→⑨、⑦→④"],"mustWrite":["R0~R3、PC","ALUop 3位、SRop 2位、SRout为三态门","⑥→⑨、⑦→④","(PC)+2：指令16位、按字节编址"],"skip":["不解释单总线原理","不写无关连线"],"pitfalls":["控制信号位数漏答","端口编号错（含④⑥⑦⑨不给分）"]},{"year":2015,"qno":44,"subject":"计算机组成原理","type":"指令编码计算题","title":"指令格式与机器码构造","score":"（未标）","budgetMin":"10","detail":"这题把指令格式、机器码和执行周期串成一条链：由操作码 7 位得出最多 2^7=128 条指令；再按位段分组把三条汇编语句手算成机器码，并写出各字段对应的控制信号。执行阶段的周期数取决于需要几拍访问总线与存储器，多操作数的那条指令拍数明显更多。考场先在草稿上把位段划分写稳，分组错一位机器码就全错，最后别忘了执行周期数这一问。","kp":["指令格式","机器码","操作码","执行周期"],"answerKey":["操作码7位→最多2^7=128条","inc R1=0240H、shl R2,R1=0488H、sub R3,(R1),R2=06EAH","控制信号①0 ②mov ③mova ④left ⑤read ⑥sub ⑦mov ⑧Srout","sub R1,R3,(R2)执行阶段≥4个时钟周期、inc R1执行阶段≥2个时钟周期"],"mustWrite":["128条","三个机器码（带H）","4周期（sub R1,R3,(R2)）与2周期（inc R1）"],"skip":["不写二进制分组推导全过程"],"pitfalls":["位段分组错→机器码错","漏答执行周期数"]},{"year":2015,"qno":45,"subject":"操作系统","type":"信号量同步题","title":"缓冲区取件与寄件同步","score":"（未标）","budgetMin":"10","detail":"这题是生产者—消费者模型的变体：从 A 缓冲区取件、向 B 缓冲区寄件，既要用满/空信号量做同步，又要用互斥信号量保护同一缓冲区的并发访问。信号量按“每个缓冲区一对 Full/Empty，再加各自的 mutex，初值 1”来设，Full 与 Empty 的初值由缓冲区已有件数决定。答题时守死顺序：先 P 同步量判断能不能操作，再 P 互斥量占住临界区，退出时先 V 互斥再 V 同步，否则会死锁或漏掉互斥。","kp":["信号量","PV操作","互斥","同步"],"answerKey":["Full_A=x、Empty_A=M−x、Full_B=y、Empty_B=N−y、mutex_A=mutex_B=1","取件：P(Full_A)P(mutex_A)→V(mutex_A)V(Empty_A)","寄B：P(Empty_B)P(mutex_B)→V(mutex_B)V(Full_B)"],"mustWrite":["5个信号量及初值","先P同步量再P互斥量"],"skip":["不写框架代码"],"pitfalls":["同步/互斥量顺序颠倒","漏mutex"]},{"year":2015,"qno":46,"subject":"操作系统","type":"分页存储计算题","title":"二级页表页数与页目录","score":"（未标）","budgetMin":"10","detail":"这题考分页系统的容量与页表层次：页和页框都是 4KB，于是虚存空间被切成 2^20 个页面；再把页目录本身和一级页表占用的页数折算进去，总页数才完整。最后一问考两个虚地址是否落在同一个二级页表——比较高位页目录号是否相同即可判断。考场先统一单位、数值都带单位，页目录项与页表项的页数别分开算漏。","kp":["分页存储","页表","页目录","虚拟地址"],"answerKey":["页与页框均2^12B=4KB","虚存空间2^32/2^12=2^20页","(2^10×4)/2^12+(2^20×4)/2^12=1025页","两地址最高10位都是4→同一二级页表"],"mustWrite":["4KB","2^20页","1025页","“需访问一个二级页表”+页目录号相同"],"skip":["不写页表项字段结构"],"pitfalls":["数值不带单位","页目录/页表页数算漏"]},{"year":2015,"qno":47,"subject":"计算机网络","type":"DHCP综合题","title":"DHCP地址分配与网关故障","score":"（未标）","budgetMin":"10","detail":"这题围绕 DHCP 与网络排障：先按主机号位数算出可分配地址范围；再默写 Discover 报文的源地址 0.0.0.0、目的地址为全 1 广播，以及两种情形下的目的 MAC——广播是 ff-ff-ff-ff-ff-ff，直接发给服务器则是服务器网卡地址。第三问是推理题：掩码正确说明网段判断没问题，能访问本地 WWW 却出不了网，只能解释为默认网关被配错。考场按“地址范围→报文头→故障定位”三轮作答，两个 MAC 千万别写反。","kp":["DHCP","IP地址","MAC地址","网关"],"answerKey":["范围111.123.15.5~.254","Discover源0.0.0.0、目的全1","目的MAC：ff-ff-ff-ff-ff-ff、00-a1-a1-a1-a1-a1","主机1能访问WWW不能访问Internet：网关误配111.123.15.2（应.1）"],"mustWrite":["源0.0.0.0、目的全1","两个MAC","“掩码正确、网关配错”"],"skip":["不写DHCP四步"],"pitfalls":["两个MAC写反","范围含.1~.254"]},{"year":2016,"qno":41,"subject":"计算机网络","type":"TCP计算分析题","title":"TCP窗口与序号速率计算","score":"（未标）","budgetMin":"12","detail":"这题是 TCP 连接管理与流量控制的综合计算：第三次握手的确认序号要按对方初始序号 +1 推算；接收窗口要扣掉已缓存但未上交的数据；拥塞窗口按慢开始逐轮增长；发送窗口取接收窗口与拥塞窗口的较小者。随后再算下一发送序号、有效传输速率，以及连接释放的最短时间。考场先把接收窗口、拥塞窗口、发送窗口三个概念分清，再套时延带宽公式，轮次别数错。","kp":["TCP","滑动窗口","拥塞窗口","三次握手"],"answerKey":["第二次握手SYN=1、ACK=1、ack=101","接收窗口20−8=12KB；拥塞窗口1+8=9KB；发送窗口min{9,12}=9KB","下一序号20K+101=20581","速率20KB/(5×200ms)=20.48kbps","释放最短1.5×200ms=300ms"],"mustWrite":["12KB、9KB、9KB","20581","20.48kbps","300ms"],"skip":["不解释慢开始"],"pitfalls":["接收/拥塞窗口混","轮次算错（应5轮）"]},{"year":2016,"qno":42,"subject":"数据结构","type":"证明推导题","title":"k叉树叶结点数与树高","score":"（未标）","budgetMin":"10","detail":"这题是树的性质推导：由总结点数拆分、以及边数＝结点数−1＝分支数×k 两条关系联立，可解出叶结点数只由分支结点数和 k 决定，与具体形态无关。第二问给高度求叶结点数的最大与最小：最大取满 k 叉树，每层都长满，叶数按等比数列求和；最小则让每层只有一条分支、把 k 个叶全压在最底层。阅卷按推导给分，只写结果会大幅失分，边数常被误写成 n。","kp":["树的性质","k叉树","叶结点","结点数"],"answerKey":["n=n0+m、e=n−1=mk→n0=(k−1)m+1","最多的满k叉树：M1=Σk^(j−1)=(k^h−1)/(k−1)","最少的树：除根每层1分支(k−1)叶、第h层k叶→M2=1+(h−1)k"],"mustWrite":["n0=(k−1)m+1的推导","M1=(k^h−1)/(k−1)","M2=1+(h−1)k"],"skip":["不画树形图"],"pitfalls":["只给结果不给推导（分别≤2分/3分）","边数误写为n"]},{"year":2016,"qno":43,"subject":"数据结构","type":"算法设计题","title":"快排划分实现n/2分组","score":"（未标）","budgetMin":"15","detail":"这题要求把 n 个元素按大小分成两组，使其中一组恰有 ⌊n/2⌋ 个元素，本质是借快速排序的划分过程，只分组不作全排序。划分后看枢轴落位 i：i 小于目标说明答案在右段，续划右段；i 大于目标则续划左段；恰好落位即完成。因为只沿一侧继续，平均时间 O(n)、额外空间 O(1)，用 low/high 保存区间的非递归写法更稳。得分点在设计思想、划分正确性与非递归实现，若改用全排序会被降档。","kp":["快速排序","划分","非递归","平均时间复杂度"],"answerKey":["快排思想：按枢轴划分，枢轴落在⌊n/2⌋即完成分组","i<⌊n/2⌋续划i之后，i>⌊n/2⌋续划i之前","非递归实现，low/high保存区间","平均时间O(n)、空间O(1)"],"mustWrite":["设计思想：仿快排、只分组不全排序","非递归实现（low/high/flag）","平均时间O(n)、空间O(1)"],"skip":["不写完整可编译代码"],"pitfalls":["按平均时间复杂度给分：O(n)=13分、O(nlogn)=11分、O(n²)=9分、其他=7分","用全排序（nlogn）→降档","划分指针边界出错"]},{"year":2016,"qno":44,"subject":"计算机组成原理","type":"中断I/O计算题","title":"中断I/O开销与响应过程","score":"（未标）","budgetMin":"10","detail":"这题把串口传输速率、中断开销和中断响应过程串起来算：先按每字符位数和中断间隔得出最高字符率，再把单字符的查询、传输与开销折成时钟周期数，进而算出总量与 CPU 实际占用，从而说明中断方式下 CPU 负担很小。最后一问是默写中断响应的三件事：关中断、保护断点、识别中断源。考场先统一到时钟周期再乘除，别把每字符位数写少。","kp":["中断","I/O方式","时钟周期","中断响应"],"answerKey":["每字符10位；最多1000/0.5=2000字符/s","时钟20ns；单字符≈2.5×10^4+10+15×4=25070周期","1000字符≈25070000周期；CPU≈9×10^4周期","中断响应：关中断、保护断点、识别中断源"],"mustWrite":["10位；2000字符/s","25070000周期；9×10^4周期","关中断、保护断点、识别中断源"],"skip":["不逐条分析指令细节"],"pitfalls":["总位数写9（仅1分）","漏算CPU时间"]},{"year":2016,"qno":45,"subject":"计算机组成原理","type":"存储层次计算题","title":"虚拟地址与Cache组划分","score":"（未标）","budgetMin":"12","detail":"这题是一张地址字段划分表：页大小决定页内偏移位数，从而定出虚页号与物理页号位数；块大小决定块内地址，Cache 的路数、每组容量和总容量决定组号位数，剩余高位就是标记。答完位宽还要比较两处替换策略的代价，说明缺页要访问磁盘、开销远大于 Cache 缺失。考场在草稿上画一遍字段划分再填数，标记位与组号位最容易被互换。","kp":["虚拟地址","TLB","Cache映射","地址划分"],"answerKey":["页8KB→页内13位：A=B=19、D=13；C=11","块64B→G=6；2路、每组128B、共512组→F=9；E=24−6−9=9","缺页开销大（访问磁盘）；Cache-主存可直写、主存-外存回写"],"mustWrite":["A=B=19、C=11、D=13、E=9、F=9、G=6","B为虚页号","Cache组3、H=0 0000 1000B"],"skip":["不画地址字段划分图"],"pitfalls":["E与F位数互换","块号二进制分组错"]},{"year":2016,"qno":46,"subject":"操作系统","type":"调度简答题","title":"静态优先级饥饿与动态调整","score":"（未标）","budgetMin":"8","detail":"这题考调度算法的公平性：静态优先数一旦确定，只要不断有更优先的进程就绪，低优先进程就可能长期得不到 CPU，这就是饥饿。改进办法是把优先数做成动态量——随已占用 CPU 时间增大、随等待时间减小，公式里要同时体现 nice、cpuTime 和 waitTime 及其符号。要点是说清 waitTime 项的方向：等得越久优先数越小，才能被及时调度。答题注意本题约定“数小优先”，方向写反就全错。","kp":["进程调度","优先级","饥饿","动态优先数"],"answerKey":["静态优先数→总有优先数小的进程就绪，优先数大的进程饥饿","priority=nice+k1×cpuTime−k2×waitTime（k1,k2>0）","waitTime使久等进程优先数减小，避免饥饿"],"mustWrite":["饥饿现象及原因","公式含nice、cpuTime、waitTime及符号","waitTime的作用"],"skip":["不写调度程序伪代码"],"pitfalls":["优先数方向搞反（数小优先）","漏waitTime项"]},{"year":2016,"qno":47,"subject":"操作系统","type":"FAT文件系统计算题","title":"FAT文件系统簇链与容量","score":"（未标）","budgetMin":"10","detail":"这题考 FAT 文件系统的目录项与簇链：目录项里存的是文件首簇号，后续簇靠 FAT 表项逐个串成链，所以“某簇号记在哪个表项”一定要分清表项下标与簇号。容量方面由表项宽度推最多簇数，再乘簇大小得 FAT 与单文件的上限。最后按文件字节数算出需要顺序访问哪几个簇。考场先画一张“目录项→首簇→表项链”的小图，别只答一个簇号。","kp":["FAT","文件系统","簇","目录项"],"answerKey":["dir:dir1→48；dir1:file1→100、file2→200","FAT簇号2B→最多2^16个表项/簇","FAT最大128KB；文件最大256MB","106簇存于100号表项，108簇存于106号","5000字节需访问48号簇与106号簇"],"mustWrite":["dir1→48、file1→100、file2→200","100←106、106←108"],"skip":["不写查找流程"],"pitfalls":["表项/簇号错位","只答一个簇号"]},{"year":2017,"qno":41,"subject":"数据结构","type":"算法设计题","title":"表达式树中序输出中缀式","score":"15分","budgetMin":"15","detail":"这题要求由表达式树输出中缀表达式并补必要括号：中序遍历得到的操作数次序就是中缀次序，但树的结构信息丢失了，必须靠括号还原。策略是只有分支结点（子表达式）才加括号，根结点和叶子（操作数）不加；递归时用深度参数控制，进入左子树前输出左括号、退出右子树后输出右括号。每个结点访问一次，时间 O(n)。考场要保证括号成对且嵌套不过量，多加括号会被降档。","kp":["表达式树","中序遍历","括号","递归"],"answerKey":["表达式树中序序列加必要括号即中缀表达式，用中序遍历","分支结点子表达式按位置定计算次序","根结点与叶（操作数）不加括号","实现：deep>1时进左子树前打(、出右子树后打)","时间O(n)（每结点访问一次）"],"mustWrite":["中序遍历+加括号策略","根与叶不加括号","deep参数控制括号层级","写出递归实现框架"],"skip":["不写完整main与建树代码"],"pitfalls":["括号嵌套层数过多→降档","左右括号数不匹配"]},{"year":2017,"qno":42,"subject":"数据结构","type":"最小生成树题","title":"Prim选边顺序与MST唯一性","score":"（未标）","budgetMin":"10","detail":"这题用 Prim 手工模拟：从起点集合出发，每一步都在连接集合内外的边里选权值最小的一条，把新顶点并入集合，逐条记录选取次序与权值，最后判断该图的 MST 是否唯一。第二问考唯一性的判定：若任一环中各边权互不相同，则 MST 唯一，这是充分条件而非必要条件，不能说“边权都不同”才唯一。答题要写清每条边的选取理由，边序错只给部分分。","kp":["最小生成树","Prim算法","贪心","唯一性"],"answerKey":["Prim属贪心：每次选连接S与外部的最小权边","依次选(A,D)、(D,E)、(C,E)、(B,C)","图G的MST唯一","任一环中各边权均不同→MST唯一（充分条件）"],"mustWrite":["四条边及次序","MST唯一","充分条件句"],"skip":["不写Prim伪代码与正确性证明"],"pitfalls":["边序错→只给部分分","把“所有边权不同”当必要条件"]},{"year":2017,"qno":43,"subject":"计算机组成原理","type":"整数/浮点分析题","title":"无符号与浮点函数转换分析","score":"（未标）","budgetMin":"12","detail":"这题把无符号整数运算与 IEEE 754 单精度放在同一组函数里对比：无符号比较下 0−1 会回绕成最大无符号数，比较条件恒真就成死循环；小数范围内整数可精确表示，两者机器码一致；而当有效位数不够时发生舍入，两个函数的结果会差 1；全 1 的机器数按带符号解释又是 −1。最后一问由正无穷的机器码反推不溢出与能精确表示的 n 的上界。考场先定住阶码偏移与有效位数这两个前提，再逐问代入。","kp":["浮点数","IEEE754","无符号数","舍入"],"answerKey":["unsigned比较：n=0时n−1=2^32−1，条件永真→死循环","f1(23)=f2(23)=2^24−1；机器码00FF FFFFH、4B7F FFFFH","n=24时f2(24)比f1(24)大1（float只有24位有效位，舍入）","f1(31)的机器数为32个1，按int解释返回−1；使f1(n)与f2(n)返回值相等的最大n=30","7F80 0000H=+∞；不溢出n≤126、精确n≤23"],"mustWrite":["死循环原因（无符号比较）","00FF FFFFH、4B7F FFFFH","f2(24)比f1(24)大1","f1(31)返回−1","n=30","n=23、n=126"],"skip":["不写完整二进制展开"],"pitfalls":["把n−1当−1解释","阶码偏移算错"]},{"year":2017,"qno":44,"subject":"计算机组成原理","type":"指令系统分析题","title":"CISC机器码与CF标志分析","score":"（未标）","budgetMin":"10","detail":"这题从指令系统层面判断类型：指令长度不一是 CISC 的典型特征；再由首末地址算指令机器码长度，务必“末地址−首地址+1”。第二问考减法对标志位的影响：0 减去全 1 会向高位借位，故进位/借位标志被置位。第三问是易错点：浮点机器数含阶码，整体左移一位并不等于数值乘 2，所以不能用逻辑左移指令实现乘 2。考场按“结论+理由、字节数算式、标志位、反例”四段作答。","kp":["CISC","机器码","标志寄存器","移位"],"answerKey":["M为CISC（指令长短不一）","f1机器码96B：0040 107FH−0040 1020H+1=60H","CF=1（0减FFFFFFFFH产生借位）","不能用shl实现power*2：float机器数含阶码，整体左移≠乘2"],"mustWrite":["CISC+理由","96B及算式","CF=1","不能用shl+理由"],"skip":["不分析每条指令微操作"],"pitfalls":["末地址−首地址忘+1","CF答0"]},{"year":2017,"qno":45,"subject":"操作系统","type":"分页与进程状态题","title":"代码页判定与进程状态转换","score":"（未标）","budgetMin":"9","detail":"这题把分页地址翻译与进程状态机绑在一起：先由两条指令虚地址高位相同判定它们落在同一页，从而得出代码只占一页；再讲页目录号定位页表、页表索引定位页，某条指令的高位字段直接给出要访问页目录和页表的第几项。第三问是进程 P 在执行中被输入阻塞、再被中断唤醒、最后被调度运行的状态转换，同时说明中断使 CPU 从用户态进入内核态。状态转换漏掉就绪态是常见失分。","kp":["分页","页目录","进程状态","用户态内核态"],"answerKey":["f1指令虚地址高20位相同→代码在同一页，仅占1页","页目录号定位页表、页表索引定位页","push ebp页目录号=1、页表索引=1→访问页目录第1项、页表第1项","P：执行→阻塞（等输入）→就绪（中断唤醒）→运行（调度）","CPU由用户态变内核态"],"mustWrite":["仅占1页+理由","页目录第1个表项、页表第1个表项","三个状态转换","用户态→内核态"],"skip":["不逐位展开地址"],"pitfalls":["状态转换漏就绪态","页目录号/页表索引写错"]},{"year":2017,"qno":46,"subject":"操作系统","type":"信号量互斥题","title":"三线程读写共享变量互斥","score":"（未标）","budgetMin":"8","detail":"这题考“哪些访问真正需要互斥”：一读一写或双写才算冲突，每个冲突关系配一个初值为 1 的信号量，各自在自己的临界区前 P、后 V，成对包住对共享变量的修改。而两个线程都只读同一变量时彼此不冲突，不必互斥，这一点要在答案里专门说明，否则会多设信号量或漏掉真正冲突。只用一个互斥信号量统一包住所有访问，得分会非常低。","kp":["信号量","互斥","PV操作","线程同步"],"answerKey":["一读一写或双写即互斥，每个互斥关系配一个信号量","mutex_y1=1（thread1与thread3）、mutex_y2=1（thread2与thread3）、mutex_z=1","各线程add前P、后V成对"],"mustWrite":["三个信号量名与初值1","P/V成对包住add","说明thread1与thread2不必互斥"],"skip":["不写完整线程代码"],"pitfalls":["只用一个互斥信号量（≤2分）","漏thread3对y的互斥"]},{"year":2017,"qno":47,"subject":"计算机网络","type":"GBN滑动窗口计算题","title":"GBN窗口与信道利用率","score":"（未标）","budgetMin":"10","detail":"这题考 GBN 的确认语义与窗口约束：接收方给出的确认号是“期望收到的下一个序号”，据此可反推已正确接收的帧数；序号位数决定发送窗口上界为 2^n−1，再结合已发帧算出还能继续发几帧、首帧与末帧是哪个。超时后要整窗回退重发，首帧与此时应携带的确认号都要写准。最后按信道利用率公式计算比例，分母别漏一个往返传播时延项。","kp":["GBN","滑动窗口","信道利用率","重传"],"answerKey":["可断定乙方已收S0,0、S1,0、S2,0共3帧","序号3位→窗口最大7；已发S3,0、S4,1，最多再发5帧（首S5,2、末S1,2）","S2,0超时重发3帧，首帧S2,3（确认号应为3）","U=7Td/(RTT+2Td)=50%（Td=8×1000/10^8）"],"mustWrite":["3帧及帧名","5帧、首帧S5,2","3帧、首帧S2,3","50%与利用率公式"],"skip":["不复述GBN"],"pitfalls":["发送窗口算成8","利用率漏2×Td项"]},{"year":2018,"qno":41,"subject":"数据结构","type":"算法设计题","title":"最小未出现正整数","score":"（未标）","budgetMin":"18","detail":"题目要在数组 A 中找出未出现的最小正整数，数组长度有限，答案一定落在 1~n+1 之间，这就把取值范围压成了有限检查。用与下标一一对应的标记数组 B 记录每个正整数是否出现过，只需一次线性扫描加一次线性回扫。考场上先说明答案范围是 1~n+1，再写标记与回扫两步，最后补上时间与空间复杂度即可。越界元素直接跳过，下标与数值差 1 的换算不能写反。","kp":["数组遍历","标记数组","最小正整数"],"answerKey":["设标记数组B[n]，B[i-1]对应正整数i，初值0","遍历A：0<A[i]≤n则B[A[i]-1]=1，越界不处理","扫B，首个B[i]==0返回i+1；全标记返回n+1","时间O(n)，空间O(n)"],"mustWrite":["用B标记1~n是否出现","返回首个空位下标+1","写出O(n)时间、O(n)空间"],"skip":["完整C代码","正确性证明"],"pitfalls":["漏掉全出现时返回n+1","B下标与数值差1"]},{"year":2018,"qno":42,"subject":"数据结构","type":"图应用题","title":"最小生成树与TTL跳数","score":"（未标）","budgetMin":"14","detail":"这题把网络建设费用抽象成无向带权图的最小生成树：要求费用最少且子网内任意两点可达，正好对应 MST 的两个性质。费用就是各条边权之和，最小生成树可能不唯一，只要边权和最小都算对。第二问回到网络层，把生成树的跳数与 TTL 相比：跳数超过 TTL 的分组会在中途被丢弃，据此判断哪种方案能收到。答题顺序是先抽象成图、再答总费用、最后用跳数判可达。","kp":["最小生成树","Prim算法","Kruskal算法","邻接矩阵"],"answerKey":["抽象为无向带权图最小生成树，总费用16","方案1、方案2均为MST，都合法","存储用邻接矩阵或邻接表；Prim或Kruskal","TTL=5：方案1跳数超限收不到，方案2可收到"],"mustWrite":["最小生成树、总费用16","存储结构+Prim(或Kruskal)","方案1收不到、方案2收到"],"skip":["逐步画生成过程"],"pitfalls":["只给一种方案","TTL判断不写结论"]},{"year":2018,"qno":43,"subject":"计算机组成原理","type":"分析计算题","title":"程序查询中断与DMA","score":"（未标）","budgetMin":"15","detail":"三种 I/O 方式的取舍由 CPU 开销和响应时限共同决定：程序查询要反复读取状态，中断方式每次传送都要打断 CPU，DMA 以数据块为单位、只在开始和结束时打扰 CPU。判断能否用中断的关键是比较中断处理时间与设备数据保持时间——处理不及时数据就会被新数据覆盖。答题时三种方式都要给出次数或占用率这类量化结论，并按题目的时间参数得出「某个设备不适合用中断」的判断。","kp":["程序查询方式","中断方式","DMA","CPU开销"],"answerKey":["查询：4B/2MB=2μs，每秒至少查5×10^5次","占CPU 2×10^7/500M=4%","中断处理0.8μs＞设备B的0.1μs，数据被刷新，不能用中断","DMA：40000次/s，2×10^7周期，占4%"],"mustWrite":["三种方式都给出结论/百分比4%","中断方式：不适合设备B","DMA次数40000"],"skip":["推导公式来源"],"pitfalls":["漏单位（μs、时钟周期）","中断与DMA结论写反"]},{"year":2018,"qno":44,"subject":"计算机组成原理","type":"综合计算题","title":"TLB与Cache地址映射","score":"（未标）","budgetMin":"18","detail":"题目串起了虚实地址转换与 Cache 组织两条主线：先由页大小定出物理地址位数，再按地址划分求出标记、组号和块内偏移。容量计算要把有效位、修改位、标记位和 LRU 位都算进去，漏掉任何一类都会算错。命中判断必须与自己的地址划分保持一致，先定位到组、再比较标记。考场上建议先画一张地址字段划分表，再逐问填数据。","kp":["TLB","Cache","组相联映射","LRU替换"],"answerKey":["物理地址28位","TLB全相联，每项一个比较器，用SRAM","2路组相联需1位LRU位；回写每行1位修改位","容量8×2×(20+1+1+1+32×8)=4464位=558字节","008CH→0040040H不命中；该地址映射组号3"],"mustWrite":["物理地址28位","Cache容量558字节","0040040H不命中、组号3"],"skip":["逐字段解释地址含义"],"pitfalls":["漏有效位致命中判断反","容量漏算标记位"]},{"year":2018,"qno":45,"subject":"操作系统","type":"简答计算题","title":"两级页表地址转换","score":"（未标）","budgetMin":"12","detail":"32 位地址先按页大小切成虚页号和页内偏移，两级页表再把虚页号拆成页目录号和页号，拼接顺序决定了最终是哪个十六进制地址。PDBR 存放页目录表的物理基址，它属于进程的地址空间现场，所以进程切换必须更换、同一进程内的线程切换不更换。最后一问考查页面置换算法的改造：改进型 CLOCK 要同时利用访问位和修改位，优先淘汰既干净又久未使用的页。","kp":["两级页表","页目录","地址转换","CLOCK算法"],"answerKey":["32位地址：高20位虚页号、低12位页内地址；页目录号10位+页号10位","十六进制0180 6008H","PDBR存页目录表物理基址；进程切换变、线程切换不变","改进型CLOCK需使用位（访问字段）和修改位（脏位）"],"mustWrite":["写出0180 6008H","进程切换会变、线程切换不变","设置访问位与修改位"],"skip":["展开进程/线程定义"],"pitfalls":["字段拼接顺序写错","PDBR两问只答一半"]},{"year":2018,"qno":46,"subject":"操作系统","type":"计算题","title":"索引结点与最大文件长度","score":"（未标）","budgetMin":"12","detail":"这题用「一个索引结点管多少块、一块能放多少地址项」的两层乘法求文件最大长度，逐级把直接、一级、二级、三级索引能覆盖的字节数相加。索引结点的总数决定文件个数上限，与文件大小配合即可算出。最后一问考的是访问路径长短：只用直接项的文件不需要额外索引块，用到间接索引就要多读盘。答题务必带单位换算，并说明结论依据在哪一级索引。","kp":["索引结点","直接地址项","多级索引","最大文件长度"],"answerKey":["每簇4KB/4B=1024个地址项","最大文件32KB+4MB+4GB+4TB","索引节点64M→最多存64M个5600B文件","F1只用直接项；F2需读一级索引表，时间不同"],"mustWrite":["最大文件长度32KB+4MB+4GB+4TB","64M个文件","F1、F2分别说明依据"],"skip":["写完整计算过程"],"pitfalls":["漏单位换算","只说不同不给依据"]},{"year":2018,"qno":47,"subject":"计算机网络","type":"计算题","title":"子网划分与IP分片","score":"（未标）","budgetMin":"14","detail":"子网划分先用掩码定出网络号与主机号，主机号全 0 是网络地址、全 1 是广播地址，可分配地址要去掉这两个，已占用的（含路由器接口）也要扣掉。第二问是 IP 分片：数据部分按 MTU 减去首部后向下取 8 的整数倍，片偏移以 8 字节为单位。判断广播覆盖范围时看清各子网的地址空间即可。答题把地址、可用数量和偏移逐项写出，不要只给结论。","kp":["子网划分","广播地址","IP分片","片偏移"],"answerKey":["广播地址=主机号全1；技术部192.168.1.128，销售部广播192.168.1.127","技术部可分配126台，已用81（含路由器），还可45台","每片最多776B（(800-20)取8的倍数）","分片2个，偏移0与97"],"mustWrite":["192.168.1.128、192.168.1.127","还可分配45台","776B、偏移0和97"],"skip":["解释划分子网原理"],"pitfalls":["忘减2个特殊地址","分片长度未取8的倍数"]},{"year":2019,"qno":41,"subject":"数据结构","type":"算法设计题","title":"链表分半逆置后交叉合并","score":"（未标）","budgetMin":"18","detail":"这题的本质是把单链表的后半段原地逆置，再把前后两段结点交替拼接，目标空间复杂度是 O(1)。用快慢指针找中间结点，逆置时保存后继指针，合并时要处理两段长度不等的情况。只要指针操作写清楚、明确每一步的时间与空间开销，不需要写完整可编译的代码。若借用栈或数组辅助，空间就不再是 O(1)，会被扣分。","kp":["单链表","快慢指针","原地逆置","空间复杂度"],"answerKey":["先找中间结点：p走一步、q走两步","后半段原地逆置（不能借助栈）","前后两段依次各取一结点交替插入","时间O(n)，空间O(1)"],"mustWrite":["三段：找中点→逆置→合并","写清指针操作（p、q、r、s）","T(n)=O(n)、S(n)=O(1)"],"skip":["写完整可编译代码"],"pitfalls":["用栈或数组使空间变O(n)","合并处指针断链"]},{"year":2019,"qno":42,"subject":"数据结构","type":"结构设计题","title":"循环链表实现队列","score":"（未标）","budgetMin":"14","detail":"队列要求入队出队都是 O(1) 且空间能动态增长，顺序存储无法随入队动态扩空间，因此选择链式结构。为了复用出队后不释放的结点，用两段式单向循环链表：一个段放已入队元素，另一个段是空闲结点，出队时把结点归还到空闲段。队空与队满的判定条件因此不同，队满时还需要新开辟空闲结点。答题重点是把两种判定条件和两种操作的时间复杂度写清楚。","kp":["队列","循环链表","队空队满判定"],"answerKey":["顺序存储无法随入队动态扩空间，选链式","出队结点不释放、可循环利用，用两段式单向循环链表","front、rear指针；队空front==rear","队满front==rear->next；入队出队均O(1)"],"mustWrite":["选两段式单向循环链表","队空与队满判定条件","入队、出队时间O(1)"],"skip":["写全部代码"],"pitfalls":["队空队满条件混淆","队满时忘开辟空闲结点"]},{"year":2019,"qno":43,"subject":"操作系统","type":"同步算法题","title":"碗信号量解决哲学家进餐","score":"（未标）","budgetMin":"12","detail":"哲学家进餐的死锁根源是「每人先拿一只筷子再等另一只」，因此只要保证同时进餐的人数不超过 n−1，就不会形成环路等待。碗的数量取人数上限与现有碗数中的较小者，先申请碗再申请筷子，形成「拿碗→拿筷→吃→放筷→放碗」的顺序。相邻筷子数组中右筷的下标要用取模得到，位置不能写错。关键是 P(bowl) 必须放在最前、V(bowl) 放在最后。","kp":["信号量","PV操作","死锁避免","进程同步"],"answerKey":["碗资源量取min(n-1,m)，保证最多n-1人同时进餐","先P(bowl)，再P左筷、P右筷；餐后V筷、V(bowl)","chopsticks[i]初值1，右筷下标(i+1)%n"],"mustWrite":["bowl=min(n-1,m)及理由","P(bowl)在最前、V(bowl)在最后"],"skip":["抄题目哲学家背景"],"pitfalls":["先取筷后取碗仍会死锁","漏V(bowl)"]},{"year":2019,"qno":44,"subject":"操作系统","type":"计算题","title":"磁盘地址结构与SSTF调度","score":"（未标）","budgetMin":"15","detail":"磁盘地址解析通常先从「柱面数×磁头数×扇区数×扇区大小」求容量，再把块号逐级除以每柱面扇区数、每磁道扇区数，得到柱面号、磁头号和扇区号。题目给出的块号往往以半扇区为单位，转成扇区号时不要漏乘。SSTF 每次都要在当前磁头位置重新找最近的请求，顺序不能一次排好。答题时容量要带单位，访问顺序和三个地址分量逐项写出。","kp":["磁盘容量","柱面磁头扇区","SSTF","磁盘调度"],"answerKey":["容量=300×10×200×512B=3×10^5KB","SSTF顺序：100260→101660→110560→60005","柱面号⌊100530/1000⌋=100","磁头号⌊530/100⌋=5；扇区号(530×2)%200=60"],"mustWrite":["3×10^5KB（带单位）","SSTF访问顺序","柱面100、磁头5、扇区60"],"skip":["推导柱面簇数"],"pitfalls":["簇号转扇区漏乘2","SSTF未逐次重找最近"]},{"year":2019,"qno":45,"subject":"计算机组成原理","type":"分析计算题","title":"递归调用与溢出判断","score":"（未标）","budgetMin":"15","detail":"这题把高级语言函数的调用过程与机器级实现对应起来：递归调用次数由参数变化决定，转移指令要区分条件转移与无条件转移，条件不满足时就顺序执行。相对寻址的偏移量是目标地址与转移指令下一条指令地址之差，用补码表示，容易与当前 PC 搞混。溢出判断看运算结果的高位是否为全 0 或全 1，溢出后要么加自陷指令、要么改变返回类型。答完三问要给出寄存器或地址的具体形式。","kp":["转移指令","相对寻址","补码","溢出判断"],"answerKey":["f1(10)调用10次","jle为条件转移，n≤1转0040 1035H；call/jmp/ret必跳","下条0040 102AH；偏移FFFF FFD6H","f(13)=6227020800溢出，返回类型改double/long long","高33位非全0/全1→OF=1，加溢出自陷指令"],"mustWrite":["FFFF FFD6H与小端","OF=1并说明自陷指令"],"skip":["抄指令执行过程"],"pitfalls":["用下条指令PC算偏移","漏改返回类型"]},{"year":2019,"qno":46,"subject":"计算机组成原理","type":"计算题","title":"指令Cache组相联映射","score":"（未标）","budgetMin":"12","detail":"第一问用页大小把虚拟地址切成虚页号与页内偏移，比较两条指令所在地址的高位即可判断是否同页。第二问是 Cache 的地址划分：块大小决定块内偏移位数，块数与路数决定组数、进而决定组号位数，剩下的高位就是标记。由于物理地址低位与虚地址低位相同，判断某地址落到哪个组只需看中间的组号字段。答题先把三个字段的位数写全，再代入具体地址。","kp":["Cache","组相联映射","地址划分","虚页号"],"answerKey":["页4KB→虚页号高20位；push与ret高20位同为00401H，同页","指令Cache 64块4路→16组（组号4位）；块64B→块内6位","32位地址：高22位标记、中4位组号、低6位块内","0040 1025H低12位025H，其7~10位为组号0"],"mustWrite":["组号4位、块内6位、标记22位","Cache组号0"],"skip":["重复虚页号推导"],"pitfalls":["组号位数由64块误算","忽略物理地址低12位与虚址相同"]},{"year":2019,"qno":47,"subject":"计算机网络","type":"综合应用题","title":"广播域隔离与NAT配置","score":"（未标）","budgetMin":"13","detail":"这题综合了设备选型与网络层行为：集线器和交换机不隔离广播域，只有路由器隔离，所以需要划分广播域的位置必须放路由器。网关地址一般取子网中的第一个可用地址，路由器接口本身也占一个地址。再看地址类型判断是否需要地址转换，私有地址访问外网必须经过 NAT。广播报文只在本广播域内传播，据此判断哪台主机能收到。","kp":["广播域","路由器与交换机","NAT","默认网关"],"answerKey":["无VLAN交换机不隔离广播域，路由器隔离→设备1路由器、设备2和3交换机","IF1配192.168.1.254；网关.1与.65","H1～H4均为私有IP地址，R需提供NAT","H3发往192.168.1.127为本网广播，只有H4收到"],"mustWrite":["设备1路由器、设备2和3交换机及理由","192.168.1.254与两个网关地址","只有H4收到"],"skip":["不罗列私有地址段"],"pitfalls":["只答设备类型无理由","广播域判断错"]},{"year":2020,"qno":41,"subject":"数据结构","type":"算法设计题","title":"三数组元素距离最小","score":"（未标）","budgetMin":"18","detail":"题目要求三个数组中各取一个元素使距离最小，直接三重枚举是 O(n³)，不可取。距离只由三个元素中的最大值与最小值决定，因此每次只需把三者中当前最小的那个下标向后移，就能单调地逼近最优解。用一个变量记录目前的最小距离，遇到 0 可以提前结束。答题写清「比较、更新、移动最小者下标」三步与复杂度即可，不必写完整函数体。","kp":["数组遍历","贪心策略","最小距离","时间复杂度"],"answerKey":["D=2L3，关键是a与c距离最小","D_min记最小距离，初值INT_MAX；i=j=k=0","循环：算D、更新D_min；最小者的下标+1","D_min=0时结束","时间O(n)、空间O(1)"],"mustWrite":["设计思想三步：比较、更新、移动最小者下标","T(n)=O(n)、S(n)=O(1)"],"skip":["写完整函数体"],"pitfalls":["忘记D_min=0提前结束","移动的不是最小值下标"]},{"year":2020,"qno":42,"subject":"数据结构","type":"应用题","title":"二叉树判定前缀编码","score":"（未标）","budgetMin":"12","detail":"编码的二叉树表示把「根到叶的路径」与「0/1 编码」对应起来，叶结点存字符，因此译码就是顺着二进制位从根往下走，到叶子输出字符再回到根。前缀特性的判定要点是任一个编码都不能是另一个编码的前缀，在树上表现为字符必须落在叶结点，中间结点不能被占用。验证时要考虑「中途遇到已有字符」和「一路创建新结点」两种情形。答题把树的结构约定写清，再说明两种失败情形。","kp":["二叉树","前缀编码","译码","哈夫曼树"],"answerKey":["用二叉树存编码：根到叶路径即编码，叶结点存字符","译码：从左到右扫0/1，从根按位下移到叶输出，再回根重复","判前缀：建树遇非根叶结点即无前缀特性","所有位均未新建结点→无前缀特性","③处理最后一个编码位时才创建新结点则继续验证下一编码；全部编码通过验证则具有前缀特性"],"mustWrite":["编码=根到叶路径，叶结点存字符","译码走指针到叶再回根","前缀特性两种失败情形"],"skip":["写建树代码"],"pitfalls":["把内部结点当解码终点","漏未新建结点的情形"]},{"year":2020,"qno":43,"subject":"计算机组成原理","type":"分析计算题","title":"乘法指令实现与溢出","score":"（未标）","budgetMin":"13","detail":"同一个乘法可以用不同层次实现：用软件循环逐位相加移位、用硬件控制逻辑完成一次乘法、或直接用单周期乘法指令，速度依次变快。溢出判断的关键是看结果的高位部分：无符号数高 n 位全 0 才算不溢出，补码则要求高位全 0 或全 1，两者条件不同，题目正是要区分。答题先说明乘法可以用加法与移位实现，再给出两种乘法的溢出结论与依据。","kp":["乘法实现","加法移位","溢出判断","无符号乘法"],"answerKey":["乘法可用加法+移位，编译器生成循环段","控制逻辑控制循环次数及加、移位操作","①最长（软件循环）、③最短（单周期乘法指令）","n=32时2^31−1乘2的积为0000 0000 FFFF FFFEH；int溢出","无符号乘法高n位全0不溢出"],"mustWrite":["说明乘法可用加法与移位","imul溢出、umul不溢出及依据"],"skip":["不展开循环细节"],"pitfalls":["三种实现快慢排序写反","只给结论不说高n位判断"]},{"year":2020,"qno":44,"subject":"计算机组成原理","type":"计算题","title":"8路组相联Cache缺失统计","score":"（未标）","budgetMin":"15","detail":"地址划分由块大小和组数共同决定：块大小给块内偏移，组数给组号，其余高位是标记。路数只影响替换算法所需的状态位，与地址字段无关，这是最容易算错的地方。缺失次数要看程序对数组的访问模式——顺序访问时每个数据块的首次访问必然缺失，同一块内的后续访问则命中。写回与写直达还决定着是否需要修改位，答题时先写清地址字段位数，再给出缺失次数和代入的具体组号与标记。","kp":["Cache","组相联映射","LRU","缺失次数"],"answerKey":["块64B→块内6位；64组→组号6位；标记20位","8路→每行3位LRU；直写→无修改位","0080 00C0H在块首；数组占64块，每块首访缺失→缺失64次","0001 0003H组索引0，初始有效位0→缺失；标记填00010H"],"mustWrite":["地址划分6/6/20位","缺失64次","组号0、标记00010H"],"skip":["逐字段解释"],"pitfalls":["误算LRU位数","把首访缺失算成每元素缺失"]},{"year":2020,"qno":45,"subject":"操作系统","type":"同步设计题","title":"前驱图同步PV设计","score":"（未标）","budgetMin":"11","detail":"前驱图描述进程之间的先后约束，每条约束用一个初值为 0 的信号量表示：前驱结点执行完做 V，后继结点开始前做 P。C 必须等 A 和 B 都完成，所以它前面要有两个 P，缺一不可；E 同理要等 C 和 D。这类题不需要互斥信号量，多写反而画蛇添足。答题把信号量名、初值以及每次 P/V 的位置对号入座即可。","kp":["信号量","PV操作","前驱关系","进程同步"],"answerKey":["4个同步关系，设SAC、SBC、SCE、SDE初值均0","A后V(SAC)；B后V(SBC)","C前P(SAC)、P(SBC)，C后V(SCE)","D后V(SDE)；E前P(SCE)、P(SDE)"],"mustWrite":["四个信号量名及初值0","各操作的P/V配对位置"],"skip":["不写互斥信号量"],"pitfalls":["C要等A、B两个P","E要等C、D两个P，漏一个"]},{"year":2020,"qno":46,"subject":"操作系统","type":"计算题","title":"二维数组分页地址转换","score":"（未标）","budgetMin":"16","detail":"分页之下数组元素的虚地址由「数组起始虚地址 + 行偏移 + 列偏移」得到，再按页大小切成虚页号与页内偏移，经页目录、页表两级翻译成物理地址。目录项地址要用页目录基址加上目录号乘 4（每项 4 字节），页表项同理，很容易漏乘。最后一问考访问局部性：按行遍历时同一行元素落在同一页，换页少；按列访问则每换一列就换页。答题把两级偏移和两个物理地址都写出来。","kp":["分页","页目录","页表","访问局部性"],"answerKey":["页4KB存一行；a[0]虚页10800H、a[1]10801H","a[1][2]虚址1080 1008H→目录号042H、页号001H","目录项地址0020 1000H+4×42H=0020 1108H","页框00301H→页表项0030 1000H+4=0030 1004H","虚拟空间连续、物理可不连续","同一行元素在同一页、同一列元素在不同页，按行遍历的局部性较好"],"mustWrite":["042H、001H及两物理地址","行遍历局部性好"],"skip":["不推页大小"],"pitfalls":["目录项地址漏乘4","行列局部性说反"]},{"year":2020,"qno":47,"subject":"计算机网络","type":"计算题","title":"NAT表与报文转发","score":"（未标）","budgetMin":"13","detail":"NAT 表的建立要看内网主机主动发出的报文：源地址与源端口被替换成路由器的外网地址和端口，回程报文再反向替换回去，端口号 80 是识别的关键。表中两行要成对写清内外网的映射关系。报文逐跳转发时，源地址只在经过 NAT 的路由器处改变，目的地址则按路由与 NAT 表相应修改。答题先列 NAT 表，再按方向说明哪个字段被改写。","kp":["NAT","私有地址","IP分组转发","端口"],"answerKey":["R2的NAT表：外网203.10.2.2:80↔内网192.168.1.2:80；H1表项可不写","H2发出的P源192.168.1.2、目的203.10.2.2","R3转发后源改为203.10.2.6","R2转发后目的改为192.168.1.2"],"mustWrite":["NAT表两行（含端口80）","两个方向的地址变化结论"],"skip":["解释NAT原理"],"pitfalls":["内外网地址位置写反","漏写端口号80"]},{"year":2021,"qno":41,"subject":"数据结构","type":"算法设计","title":"邻接矩阵统计顶点度并判奇度","score":"（未标）","budgetMin":"15","detail":"考查图的邻接矩阵与顶点度数的对应关系：无向图邻接矩阵第 i 行（列）的非零元个数就是顶点 i 的度。判据来自欧拉图理论——奇度顶点数为 0 或 2 时才返回 1，否则返回 0，所以统计完每行非零元后只需对奇度点计数，不必真去搜索欧拉回路或做 DFS/BFS。下手时先说明矩阵按行统计即得度数，再补上返回 0 的分支，并把复杂度写成 O(n²)、空间 O(1)。","kp":["邻接矩阵","顶点度","奇度顶点"],"answerKey":["邻接矩阵每行(列)非零元个数=该顶点度","奇数度顶点数为0或2→返回1，否则0","时间O(n²)、空间O(1)"],"mustWrite":["写：逐行统计非零元得度数","写：奇度点计数与0/2判据","写：O(n²)/O(1)"],"skip":["不用写：DFS/BFS判定","不用写：欧拉回路构造"],"pitfalls":["漏写返回0的分支","复杂度写成O(n)"]},{"year":2021,"qno":42,"subject":"数据结构","type":"算法设计","title":"比较计数排序结果与稳定性","score":"（未标）","budgetMin":"12","detail":"考查比较计数式排序，重点在稳定性和比较次数的精确写法而非排序本身。每个元素与其余元素逐一比较、累计比自己小的元素个数，得到 b[6]={-10,10,11,19,25,25}；两两比较共 n(n-1)/2 次，所以是 O(n²) 而不能写成 O(n)。坑在相等元素：只有把计数写成 if/else 两支（相等时也给后者加一）才能保证稳定，写成单分支 if 会让相等元素次序颠倒。","kp":["计数排序","排序稳定性","比较次数"],"answerKey":["b[6]={-10,10,11,19,25,25}","全部两两比较，共n(n-1)/2次","不稳定：需加else count[i]++"],"mustWrite":["写：排序结果六个数","写：n(n-1)/2次","写：不稳定+else count[i]++"],"skip":["不用写：完整代码照抄","不用写：稳定排序通用证明"],"pitfalls":["忘加else致相等元素逆序","比较次数只写O(n²)"]},{"year":2021,"qno":43,"subject":"计算机组成原理","type":"计算分析","title":"指令格式与运算溢出判断","score":"（未标）","budgetMin":"12","detail":"考查指令格式的字段划分与定点运算的溢出判断。由地址 20 位推出 1MB 空间，ALU 16 位，MAR/MDR 位宽随之确定；R 型操作码 4 位得 16 种，I/J 型共用 6 位字段，必须减去全 0 的保留编码才是 63 种。加减与乘法的溢出要用各自的判据（真值式或双符号位）分别算，本题一个不溢出、一个溢出。imm 是带符号整数，参与地址计算前要符号扩展；无条件转移可套用 J 型格式，目标地址写入 PC 低 10 位。","kp":["指令格式","操作码编码","溢出判断","符号扩展"],"answerKey":["ALU16位；地址20位→1MB；MAR20位；MDR8位","R型4位16种；I/J型6位→2^6-1=63种","寄存器2位→4个","01B2H：B052H-0008H=B04AH未溢出","01B3H：B052H×0008H=8290H溢出","imm为带符号整数→地址计算时对imm符号扩展","无条件转移可用J型格式，target写入PC低10位"],"mustWrite":["写：ALU/MAR/MDR位宽","写：I/J型63种须减全0","写：imm符号扩展、J型target写PC低位"],"skip":["不用写：RISC/CISC对比"],"pitfalls":["I/J型写成64种","8290H判为不溢出"]},{"year":2021,"qno":44,"subject":"计算机组成原理","type":"计算分析","title":"TLB组相联与虚地址位划分","score":"（未标）","budgetMin":"8","detail":"考查 TLB 与虚拟地址的位划分。先由页大小 4KB 定出页内偏移 12 位，虚页号 18 位；TLB 是 8 组 2 路组相联，组号取 3 位，余下 15 位作标记，注意标记不能把组号算进去，否则会多一位。替换按 LRU 找出被淘汰的虚页；虚地址扩到 32 位时增加的只是虚页号位数，页表项长度相应增 2 位。","kp":["TLB","组相联映射","虚拟地址","LRU替换"],"answerKey":["页4KB=2^12→页内12位，虚页号18位","TLB8组(2路组相联)→组号3位、标记15位","第20页访问时按LRU淘汰虚页4","虚地址扩到32位→表项位数增2位"],"mustWrite":["写：12位/18位两组位数","写：组号3位、标记15位","写：淘汰虚页4+增2位"],"skip":["不用写：页表项字段枚举","不用写：地址译码流程"],"pitfalls":["标记写成16位","替换页写成20"]},{"year":2021,"qno":45,"subject":"操作系统","type":"简答分析","title":"关中断实现PV互斥的可行性","score":"（未标）","budgetMin":"7","detail":"考查用开关中断实现临界区互斥是否可行：wait/signal 中对信号量 s 的读—改—写必须整体互斥，否则会丢失唤醒。方法一的问题在于 s≤0 时关中断后就地 while 等待，中断始终关闭，别的进程再没机会修改 s，形成死循环；方法二在循环体内重新开中断，别人能改 s，因而正确。还要点明开/关中断是特权指令、只能在内核态执行，这是该方案的前提。","kp":["PV操作","临界区","开关中断","特权指令"],"answerKey":["wait/signal中对s的读改写必须互斥","方法1错：S<=0时关中断后while死循环","方法2对：循环体内开中断，别人才可改s","开/关中断是特权指令，仅内核态可用"],"mustWrite":["写：方法1错因","写：方法2对因","写：特权指令、仅内核态"],"skip":["不用写：PV完整定义","不用写：三种方案对比"],"pitfalls":["只说错不写死循环","漏写特权指令"]},{"year":2021,"qno":46,"subject":"操作系统","type":"简答分析","title":"系统引导过程与磁盘格式化","score":"（未标）","budgetMin":"6","detail":"考查系统启动与磁盘准备工作的先后次序。引导链按 ROM 引导→磁盘引导→分区引导→OS 初始化写出，磁盘侧按物理格式化→分区→逻辑格式化→安装 OS 写出，两条顺序都不能颠倒，尤其别把逻辑格式化排到分区之前。归属判断看对象：划分扇区属于物理（低级）格式化，建立根目录属于逻辑（高级）格式化。","kp":["系统引导","物理格式化","逻辑格式化"],"answerKey":["引导：ROM引导→磁盘引导→分区引导→OS初始化","磁盘操作：物理格式化→分区→逻辑格式化→安装OS","扇区划分属物理(低级)格式化；根目录属逻辑(高级)格式化"],"mustWrite":["写：两条顺序全写","写：扇区/根目录各属哪种格式化"],"skip":["不用写：分区表结构","不用写：MBR/GPT对比"],"pitfalls":["逻辑格式化排在分区之前","根目录归到物理格式化"]},{"year":2021,"qno":47,"subject":"计算机网络","type":"分析题","title":"DNS封装与交换机自学习","score":"（未标）","budgetMin":"8","detail":"综合考查 DNS 报文的逐层封装、以太网交换机自学习和 ARP 广播。DNS over UDP 的封装链按 报文→UDP→IP→CSMA/CD 帧 依次写。交换机交换表用收到帧的源 MAC 与入端口登记，t1 时刻得到 -cc→4、-bb→1、-aa→2；H2 此前没发过帧，所以表里没有它，不能凭想象给 H2 编一条表项。H2 会收到 2 个 ARP 广播帧，广播帧的目的 MAC 全 F。","kp":["DNS","UDP封装","交换机自学习","ARP广播"],"answerKey":["DNS over UDP：报文→UDP→IP→CSMA/CD帧","t1交换表：-cc→4、-bb→1、-aa→2（无H2）","H2收到2个ARP广播帧，目的MAC全F"],"mustWrite":["写：四层封装链","写：三条交换表项","写：2个帧+目的MAC全F"],"skip":["不用写：ARP字段","不用写：路由表查找"],"pitfalls":["以为H2的MAC被记录","漏答广播帧"]},{"year":2022,"qno":41,"subject":"数据结构","type":"算法设计","title":"顺序存储二叉树判为二叉搜索树","score":"（未标）","budgetMin":"16","detail":"考查二叉搜索树的判定：BST 的中序遍历序列严格升序，因此一次中序递归即可，不能只比较父子，那样会漏掉子树的取值约束。顺序存储下结点 i 的左右孩子是 2i+1、2i+2，父结点是 (i-1)/2，递归时用下标定位孩子。实现上用 val 记录已访问过的最大值，初值取负整数，每访问一个结点就与 val 比较，当前值不大于 val 立即返回 false，否则更新 val。","kp":["二叉搜索树","中序遍历","顺序存储"],"answerKey":["顺序存储：父(i-1)/2，左2i+1，右2i+2","中序为升序；val记已访问最大值（初值取负整数），当前值≤val即false","中序递归遍历，逐结点更新val"],"mustWrite":["写：BST中序升序判据","写：val初值为负整数、逐结点更新","写：返回false的确切条件"],"skip":["不用写：pmax/pmin解法代码","不用写：建树与插入"],"pitfalls":["只比较父子，漏子树约束","漏写val初值与更新"]},{"year":2022,"qno":42,"subject":"数据结构","type":"算法设计","title":"数组中最小10个数的选取","score":"（未标）","budgetMin":"12","detail":"考查从 n 个数中挑出最小的 10 个，属于典型 Top-K，用固定容量的辅助结构换取效率。用升序数组时只与 A[9]（现存最大者）比较，s 更小就淘汰 A[9] 再插入；用 10 元素大根堆时与堆顶比较，更小就删堆顶、插入 s。判据必须是现存 10 个里的最大者，堆法若与堆底比较就完全错了。扫完一遍即得到结果，平均时间 O(n)、空间 O(1)，不要误写成 O(n log n)。","kp":["大根堆","Top-K问题","时间复杂度"],"answerKey":["容量10：数组升序插入，s<A[9]则淘汰A[9]并插入","或10元素大根堆：s<堆顶则删堆顶插s","扫描完保存的即最小10个数","平均时间O(n)、空间O(1)"],"mustWrite":["写：容量10+淘汰最大者","写：s<A[9]或s<堆顶","写：O(n)、O(1)"],"skip":["不用写：完整代码","不用写：其他排序法讨论"],"pitfalls":["大根堆却与堆底比较","复杂度写成O(n log n)"]},{"year":2022,"qno":43,"subject":"计算机组成原理","type":"计算分析","title":"溢出逻辑式与单总线数据通路","score":"（未标）","budgetMin":"12","detail":"考查运算器溢出判断与单总线数据通路的暂存设计。OF 要按加、减分别写出与符号位相关的逻辑表达式，两者形式不同、不能混用。单总线上同一时刻只有一个数据有效，所以 ALU 的两个输入需用 Y 暂存、输出用 Z 暂存。由 rs、rd 各 4 位可知通用寄存器有 16 个，rd 接地址译码器选寄存器；取指过程按 PCout、MARin→Read→MDRout、IRin 数时钟，共 7 个时钟，控制信号由 CU 产生。","kp":["溢出判断","数据通路","通用寄存器","指令周期"],"answerKey":["SF=F15；加OF=A15'B15'F15+A15B15F15'","减OF=A15'B15F15+A15B15'F15'","单总线每时刻仅一个数据有效→Y暂存ALU一个输入、Z暂存ALU输出","rs/rd各4位→16个GPR，rd接地址译码器","取指PCout,MARin→Read→MDRout,IRin=1+5+1=7","控制信号由CU产生"],"mustWrite":["写：两条溢出式","写：Y暂存输入、Z暂存输出","写：16个GPR、7个时钟"],"skip":["不用写：硬布线/微程序对比"],"pitfalls":["溢出式漏项或加减混用","取指写成6个时钟"]},{"year":2022,"qno":44,"subject":"计算机组成原理","type":"计算分析","title":"磁盘地址位数与平均存取时间","score":"（未标）","budgetMin":"10","detail":"考查磁盘地址格式、平均存取时间与 DMA 传送。地址字段由柱面号、磁头号、扇区号组成，按各自数量取 2 的幂次：20000 个柱面需 15 位、4 个记录面需 3 位、500 个扇区需 9 位，位数要向上取整。平均存取时间＝寻道时间＋平均旋转延迟＋传输时间，转速 7200r/min 转一圈约 8.33ms，平均旋转延迟必须除以 2。512B 按 64 位总线传送需 64 次请求，DMA 用周期挪用方式，其访存优先于 CPU。","kp":["磁盘地址格式","平均存取时间","DMA","周期挪用"],"answerKey":["字段：柱面号、磁头号、扇区号","20000→15位；4×2面→3位；500扇区→9位","转一圈60×10³/7200≈8.33ms；平均5+8.33/2+8.33/500≈9.18ms","512B/64bit=64次总线请求，周期挪用优先DMA"],"mustWrite":["写：三字段名与15/3/9位","写：9.18ms的组成","写：64次+周期挪用"],"skip":["不用写：RAID内容"],"pitfalls":["平均延迟未除2","位数字段漏取整"]},{"year":2022,"qno":45,"subject":"操作系统","type":"计算分析","title":"索引结点共享与间接索引层级","score":"（未标）","budgetMin":"10","detail":"考查目录项、索引结点的共享关系与多级间接索引的容量判断。目录项由文件名和索引结点号构成，course→2、doc→10；doc 与 course1 共用结点 10，说明两者是同一文件的共享链接，据此定出 x=30。读 course1 要访问两个磁盘块：先读索引块、再读内容块。判断间接层级先算 6MB 折合 1536 个磁盘块，10+1024 不够、再加一级的 1024² 才够，故采用一级间接加二级间接。","kp":["索引结点","目录项","间接索引","文件共享"],"answerKey":["目录项=文件名+索引结点号；course→2、doc→10","doc与course1共用结点10→x=30","读course1需2块：索引块+内容块","6MB=1536块，10+1024<1536<10+1024+1024²→一级+二级间接"],"mustWrite":["写：x=30及共享理由","写：2个磁盘块及类别","写：1536块→一级+二级"],"skip":["不用写：目录检索算法"],"pitfalls":["把doc当独立结点","间接层级判成三级"]},{"year":2022,"qno":46,"subject":"操作系统","type":"设计题","title":"前趋图同步的信号量设置","score":"（未标）","budgetMin":"10","detail":"考查按前趋图设置信号量实现进程同步。依赖关系是 T1 的 A 先于 T2 的 C、T2 的 C 先于 T1 的 E，因此设 S_AC 与 S_CE 两个信号量，初值都为 0，表示前趋动作未完成时后继动作必须等待。T1 中 A 之后 signal(S_AC) 唤醒 T2，再 wait(S_CE) 等 C 完成才执行 E、F；T2 中 B 之后 wait(S_AC)、执行 C 后 signal(S_CE)、再执行 D。作答时两进程代码要对照写，注意 signal 与 wait 的位置，初值写成 1 就失去同步作用。","kp":["PV操作","信号量","进程同步","前趋图"],"answerKey":["同步：T1的A→T2的C；T2的C→T1的E","S_AC=0、S_CE=0，初值均为0","T1: A;signal(S_AC);wait(S_CE);E;F","T2: B;wait(S_AC);C;signal(S_CE);D"],"mustWrite":["写：两信号量名与初值0","写：T1中signal在前wait在后","写：两进程代码对照"],"skip":["不用写：信号量内部实现"],"pitfalls":["S_CE的signal放T1","初值写成1"]},{"year":2022,"qno":47,"subject":"计算机网络","type":"分析题","title":"交换机集线器判别与最小帧长","score":"（未标）","budgetMin":"10","detail":"综合考查设备类型判别、最小帧长折算距离与无线帧地址。能隔离冲突域的是交换机，集线器不能，据此判定设备 1 为交换机、设备 2 为集线器。最小帧长 64B 由发送时延加往返传播时延决定，代入式求 D 时不要漏掉往返的 2，否则会算出一半的距离。M 是 DHCP DISCOVER 广播，目的 MAC 全 F，同网段的 E0 可以收到；802.11 帧中地址 1 是接收方、地址 2 是 AP、地址 3 是发送方。","kp":["交换机","集线器","最小帧长","DHCP"],"answerKey":["设备1=100BaseT交换机，设备2=100BaseT集线器","64B=(1.51μs+D/(2×10⁸))×100Mbps→D=210m","M为DHCP DISCOVER广播，目的MAC全F，E0可收到","H5帧：地址1=E1(接收)、地址2=C1(AP)、地址3=D1(发送)"],"mustWrite":["写：两设备及隔离域理由","写：代入式与210m","写：地址1/2/3身份"],"skip":["不用写：DHCP四报文"],"pitfalls":["漏乘2得D=105m","地址2说成接收端"]},{"year":2023,"qno":41,"subject":"数据结构","type":"算法设计","title":"邻接矩阵求K顶点出度大于入度","score":"（未标）","budgetMin":"12","detail":"考查用邻接矩阵统计各顶点的出度、入度并筛选满足条件的 K 顶点。有向图邻接矩阵第 v 行非零元个数是出度、第 v 列非零元个数是入度，一次双重循环即可同时统计。判据是出度大于入度，满足就输出该顶点并将计数器加一，最后返回 cnt。常见错误是把判据写成入度大于出度，或只计数却漏了输出顶点。","kp":["邻接矩阵","出度","入度"],"answerKey":["K顶点判据：出度>入度","对每顶点v统计出度、入度，满足则输出v并cnt++","返回cnt"],"mustWrite":["写：出度>入度判据","写：输出+计数+返回cnt","写：邻接矩阵双重循环"],"skip":["不用写：完整代码照抄","不用写：邻接表改写"],"pitfalls":["判据写成入度>出度","只计数不输出顶点"]},{"year":2023,"qno":42,"subject":"数据结构","type":"算法设计","title":"置换选择排序与归并段划分","score":"（未标）","budgetMin":"12","detail":"考查置换—选择排序生成初始归并段的过程与段数分析。每步在候选集合中取大于当前 MINIMAX 的最小元素输出，并以它更新 MINIMAX；若不存在更大的元素则本段结束、开始下一段，于是序列被划成三段，段内保持升序。作答的关键是边界元素归属，尤其 166 属于第二段而非第三段。结论部分要能说明输入本身升序时每段长度最大可达 n，而最坏情况下段数只能为 m。","kp":["置换选择排序","初始归并段","MINIMAX"],"answerKey":["3段：{37,51,63,92,94,99}、{14,15,23,31,48,56,60,90,166}、{8,17,43,100}","取大于MINIMAX的最小元素并更新，无则本段结束","升序输入时新段可达n；最坏只能为m"],"mustWrite":["写：三段顺序正确","写：MINIMAX规则","写：(2)答n与m"],"skip":["不用写：18步推演"],"pitfalls":["166误划入第三段","(2)答2m"]},{"year":2023,"qno":43,"subject":"计算机组成原理","type":"计算分析","title":"缺页次数与Cache组相联命中率","score":"（未标）","budgetMin":"12","detail":"考查虚拟存储与 Cache 组相联的综合计算。先算数据量折合多少页，24×64/1024=1.5 页要向上取整为 2 页，因此发生 2 次缺页，缺页地址为 0042 2000H 和 0042 3000H；每个数组元素只访问一次，没有时间局部性可利用。Cache 侧按块内 5 位、256 块 4 路组相联推出 64 组，组号 6 位、Tag 21 位。a[1][0] 映射到 8 号组，共访问 192 块、命中 7/8 即 87.5%，按行或按列访问的命中率相同。","kp":["缺页中断","Cache映射","组相联","命中率"],"answerKey":["24×64/1024=1.5→占2页，缺页2次：0042 2000H、0042 3000H","每元素只访一次→无时间局部性","块内5位；256块4路→64组，组号6位、Tag21位","a[1][0]组号=8；192块，命中率7/8=87.5%"],"mustWrite":["写：2次缺页与地址","写：组号6位、Tag21位","写：87.5%且行列相同"],"skip":["不用写：LRU过程"],"pitfalls":["页面数写1.5未取整","组号漏算4路"]},{"year":2023,"qno":44,"subject":"计算机组成原理","type":"计算分析","title":"指令地址计算与小端序判定","score":"（未标）","budgetMin":"10","detail":"考查指令地址计算、寻址方式与小端判定。第 20 条指令的地址由首地址加位移得到；相对寻址必须以当前指令地址 0040 107BH 为基准再加 09H，用首地址去算就错了。数组元素寻址用的是立即数寻址，由 64×4×i 得 ecx=256i。判断大小端看数据 00 20 42 00 的存放顺序——低字节在低地址，故为小端。第 19 条指令的页号 00401H 已在内存，所以不缺页。","kp":["相对寻址","指令地址","小端序","页号"],"answerKey":["第20条指令=0040 10AEH+0BH=0040 10B9H","相对寻址：0040 107BH+09H=0040 1084H","立即数寻址；ecx=64×4×i=256i","00 20 42 00低字节在低地址→小端","第19条页号00401H已在内存→不缺页"],"mustWrite":["写：两个地址","写：小端结论及依据","写：不缺页结论"],"skip":["不用写：指令格式字段表"],"pitfalls":["相对寻址用当前指令地址","大小端判断反了"]},{"year":2023,"qno":45,"subject":"操作系统","type":"简答分析","title":"自旋锁进入区退出区改造","score":"（未标）","budgetMin":"6","detail":"考查自旋锁进入区、退出区的写法与 swap 指令的原子性。进入区要把 if 改成 while，锁为 TRUE 时持续等待，避免一次判断失败就闯入临界区；退出区要把 lock=TRUE 改成 lock=FALSE，原写法根本没有解锁。新的 newSwap 不能替代 swap，因为它不具原子性，执行中途被切换后两个进程都可能看到锁空闲，互斥失效。作答时两处改动与原子性理由都要写全，理由不能只说效率低。","kp":["临界区","自旋锁","原子操作","swap指令"],"answerKey":["进入区if改while：lock为TRUE时持续等待","退出区lock=TRUE改lock=FALSE（解锁）","不能替代swap：newSwap不具原子性，中途切换则互斥失效"],"mustWrite":["写：两处改动(while、FALSE)","写：newSwap非原子→不能替代"],"skip":["不用写：Peterson对比"],"pitfalls":["只改while忘改退出区","理由写成效率低"]},{"year":2023,"qno":46,"subject":"操作系统","type":"简答分析","title":"键盘中断处理顺序与进程状态","score":"（未标）","budgetMin":"8","detail":"考查键盘中断的处理流程与进程状态变化。正确顺序是 ②⑥④③①⑤，其中步骤②一定会引起进程切换——P 因等待输入而阻塞，CPU 必须转去执行其他进程；步骤①把 P 唤醒后才有条件重新调度它。步骤③由键盘驱动程序完成，仍是 CPU 执行的内核态代码。整个中断处理期间 P 处于阻塞态、CPU 处于内核态，最易出错的是把④与③的先后颠倒，或误答步骤①一定切换。","kp":["中断处理","进程状态","设备驱动程序","进程调度"],"answerKey":["正确顺序：②⑥④③①⑤","步骤②一定切换（P阻塞，CPU转其他进程）；步骤①后可调度P","步骤③由键盘驱动程序完成（CPU执行，内核态）","中断处理时P为阻塞态、CPU为内核态"],"mustWrite":["写：全序②⑥④③①⑤","写：②必切换、①后可调度","写：阻塞态+内核态"],"skip":["不用写：中断向量表细节"],"pitfalls":["④与③顺序颠倒","答步骤1一定切换"]},{"year":2023,"qno":47,"subject":"计算机网络","type":"计算分析","title":"TCP序号拥塞窗口与吞吐量","score":"（未标）","budgetMin":"12","detail":"考查 FTP 的连接特性与 TCP 序号、拥塞窗口、吞吐量的联合计算。控制连接持久、数据连接非持久，登录使用控制连接。报文段首字节序号 101、末字节 18100，FIN 要占用一个序号，所以下一个序号是 18101，第二次挥手的确认号为 18102。拥塞窗口随确认到达变化：收到 2101 时 cwnd 为 3MSS；收到 7101 时已达到门限转入拥塞避免，cwnd 为 5MSS，不能再加倍。6 个 RTT 共 60ms，18000B/60ms 得 2.4Mbps。","kp":["TCP序号","拥塞窗口","慢开始门限","吞吐量"],"answerKey":["控制连接持久、数据连接非持久；登录用控制连接","首字节101；末字节18100，FIN耗1序号→18101","第二次挥手ACK=18102","收到2101→3MSS；收到7101→达门限后拥塞避免→5MSS","6RTT=60ms，18000B/60ms=2.4Mbps"],"mustWrite":["写：101/18101/18102","写：3MSS与5MSS","写：6RTT、2.4Mbps"],"skip":["不用写：FTP模式"],"pitfalls":["FIN不占序号致18101错","拥塞避免仍加倍"]},{"year":2024,"qno":41,"subject":"数据结构","type":"算法设计题（唯一拓扑序列判定）","title":"唯一拓扑序列的判定","score":"（未标）","budgetMin":"12","detail":"题目要求用算法判断一个有向图的拓扑序列是否唯一。核心判据是每一轮在入度为 0 的顶点中若出现两个及以上，序列就不唯一（用 in0=-2 标记这种情况）；再让拓扑排序的循环执行次数与 numVertices 比较，只有每轮唯一且全部顶点都输出才返回 1。考场先想通“唯一”等价于“每一步的入度 0 候选只有一个”，再照邻接表 + 入度表的模板写即可。","kp":["拓扑排序","邻接表","入度","唯一性判定"],"answerKey":["建各顶点入度表degree[]","选入度0顶点v，其邻接点入度减1，重复","每轮入度0顶点唯一且共做numVertices次→唯一返回1，否则返回0"],"mustWrite":["写设计思想+关键注释","含degree初始化、in0=-2标记多个、free(degree)","结论返回1/0"],"skip":["不用写存储结构定义、输入输出"],"pitfalls":["漏判多个入度0顶点（in0=-2）","忘用count比较numVertices"]},{"year":2024,"qno":42,"subject":"数据结构","type":"散列表（HT）应用题","title":"散列表查找与装填因子","score":"（未标）","budgetMin":"10","detail":"题目给出散列函数与冲突处理方法，要求把给定的 7 个关键字填入 11 个槽并分析查找过程。装填因子按 α=7/11 算；查找 14 时依次比较 3、18、14；查找失败时沿探测链走到空槽，该失败的散列地址为 7。答题的关键是把 HT 画准，再把比较序列与失败地址分别落到具体槽位上——失败地址问的是槽号，不是被查的关键字。","kp":["散列表","装填因子","冲突处理","查找长度"],"answerKey":["HT共11槽，填入11、14、7、20、9、3、18","装填因子α=7/11","查找14的比较序列：3，18，14","查找8失败时的散列地址是7"],"mustWrite":["画出HT并标明7个关键字位置","写α=7/11","写比较序列与失败地址7"],"skip":["不用写散列函数推导"],"pitfalls":["槽位与关键字错位","失败地址答成8"]},{"year":2024,"qno":43,"subject":"计算机组成原理","type":"指令格式与数据通路","title":"指令格式与溢出判定","score":"（未标）","budgetMin":"10","detail":"本题围绕定长指令格式与数据通路展开：由 shamt 字段的位数反推通用寄存器最多 32 个（shamt 占 5 位）；ALU 结果 F=1FDB9753H 时有 OF=1、CF=1，而这里判断溢出要看 CF 而不是 OF；slli 只取 IR[31:20] 的低 5 位，扩展信号 Ext 取值决定 ALUctr。考场先分清“算术溢出看 OF、进位/地址型溢出看 CF”，再逐问对应字段位宽作答。","kp":["指令格式","shamt","溢出判断","数据通路"],"answerKey":["最多32个通用寄存器，shamt占5位","ALUBSrc=0；F=1FDB9753H；OF=1、CF=1，按CF判溢出","slli只用IR[31:20]低5位，Ext取0或1","Ext=1时ALUctr=000","A040A103H为lw，地址FFFF 9CD4H"],"mustWrite":["答32寄存器、shamt=5位","写F=1FDB9753H、OF=1、CF=1"],"skip":["不用写逐位展开"],"pitfalls":["用OF判溢出（应用CF）"]},{"year":2024,"qno":44,"subject":"计算机组成原理","type":"指令与存储（数组地址/机器数）","title":"数组地址与机器数表示","score":"（未标）","budgetMin":"10","detail":"本题把一次 C 数组访问落到机器级：先明确 a 首地址在 r3、i 在 r2、sum 在 r1，据此算出 a[i] 的有效地址 0013E004H 及其补码机器数 FFFFECDCH；再由地址高位取出页号 0013EH，推出数组 a 至少占 2 页。最后一问把汇编 slli r4,r2,1 反编码成机器码 00212213H。答题顺序建议“先定寄存器分配、再算地址、最后把地址拆成页号与页内偏移”，所有数值统一带 H。","kp":["寻址方式","机器数","页式存储","指令编码"],"answerKey":["a首地址在r3，i在r2，sum在r1","a[i]地址0013E004H，机器数FFFFECDCH","sum机器数0000000EH，a[i]页号0013EH，数组a至少占2页","指令机器码00212213H，汇编slli r4,r2,1"],"mustWrite":["三个寄存器结论分写","数值均带H","页数答2页"],"skip":["不用写指令编码推导"],"pitfalls":["地址与机器数混淆","页号写成地址"]},{"year":2024,"qno":45,"subject":"操作系统","type":"页式虚拟存储地址转换","title":"页式虚存地址转换计算","score":"（未标）","budgetMin":"10","detail":"本题只考地址转换的算术链：页表项地址 = 页表始址 + 页号×4，于是该虚地址对应的页表项 VA=B8C00120H、页表项物理地址 65400120H；页框号由物理地址右移 22 位得到 2EAH。第二问换了对象，要先求页表页自身的页号 2E3H，再同样定位页表项。考场务必把“页号<<2”这一公式写出来，并注意 >>22 与 <<22 的方向，写反几乎必错。","kp":["页表","地址转换","页框号","页表项"],"answerKey":["页表项VA=B8C00000H+48H<<2=B8C00120H","页表项物理地址=65400000H+48H<<2=65400120H","页框号=BAB45678H>>22=2EAH","P的页表页页号2E3H；页表项VA=B8C00B8CH，页框号195H"],"mustWrite":["写公式页表始址+页号×4","结果带H"],"skip":["不用写多级页表"],"pitfalls":["页号<<2写错","高低位错（应>>22）"]},{"year":2024,"qno":46,"subject":"操作系统","type":"同步互斥（PV操作）","title":"进程同步与临界区互斥","score":"（未标）","budgetMin":"10","detail":"题目给出两个进程对共享变量 B 的写操作，要求把“同步”和“互斥”分开处理：C1 对 B 的写必须互斥，用 mutex=1 加 wait/signal 包住；P1 在 C1 之后产出、P2 在 C2 之前才可用，这是先后次序，用初值 S=0 的 wait/signal 约束。考场先指出哪段是临界区并说明互斥理由，再分别写信号量名与初值，最后把 wait/signal 成对写全，切忌同步与互斥共用一个信号量。","kp":["PV操作","信号量","临界区","同步互斥"],"answerKey":["C1是临界区：对B写操作，P1、P2须互斥","同步用semaphore S=0；P1执行C1后signal(S)，P2先wait(S)再C2","互斥用semaphore mutex=1，两进程用wait(mutex)、signal(mutex)包住C3"],"mustWrite":["写出信号量名与初值","wait/signal成对写全","指出临界区及互斥理由"],"skip":["不用写主函数框架"],"pitfalls":["同步与互斥混用一个信号量","漏写初值"]},{"year":2024,"qno":47,"subject":"计算机网络","type":"路由协议（OSPF/BGP）","title":"OSPF与BGP路由通告","score":"（未标）","budgetMin":"12","detail":"本题把域内与域间路由放在一起考：AS4 内部应选 OSPF；跨 AS 传播要经过多个 AS，TTL 至少 16；路由获得时间随通告层次不同，210.2.3.0/24 需 ≥30s，210.2.4.0/24 需 ≥60s。eBGP 用 UPDATE 报文通告，R13 再经 iBGP 通知 R14、R15，两者下一跳分别是 R11 与 R13。考场先分清 eBGP 与 iBGP 的通告方向与下一跳归属，再核对 TTL 要写 16 而不是 15。","kp":["OSPF","BGP","自治系统","TTL"],"answerKey":["AS4选OSPF","TTL至少16","R11~R16获210.2.3.0/24路由≥30s，获210.2.4.0/24路由≥60s","eBGP用UPDATE通告，R13经iBGP通告R14、R15","R14下一跳R11，R15下一跳R13"],"mustWrite":["答AS4应选OSPF","TTL=16；30s/60s","eBGP/iBGP与下一跳"],"skip":["不用写BGP报文格式"],"pitfalls":["TTL写成15"]},{"year":2025,"qno":41,"subject":"数据结构","type":"算法设计题（乘积最大值）","title":"数组元素乘积最大值","score":"13分","budgetMin":"12","detail":"要求对每个 A[i] 求 A[i]×A[j]（i≤j）的最大值。方法一是双循环枚举，复杂度 O(n²)/O(1)；方法二是先扫一遍求出全局最大值 max 与最小值 min，再看 A[i] 的正负分别乘 max 或 min，做到 O(n)/O(1)。考场要先处理两个边界：i=j 必须允许，全负时不能一律乘 max；再写 res 的初值与循环条件。","kp":["算法设计","时间复杂度","最值扫描","边界条件"],"answerKey":["方法1：双循环i≤j，取A[i]*A[j]最大值存res[i]","方法2：先求A的最大值max与最小值min","A[i]<0乘min，A[i]>0乘max","方法1为O(n²)/O(1)，方法2为O(n)/O(1)"],"mustWrite":["写函数原型与关键注释","写复杂度O(n²)/O(1)或O(n)/O(1)","res初值与条件写全"],"skip":["不用写main与输入输出"],"pitfalls":["漏i=j（须允许相等）","全负时误乘max"]},{"year":2025,"qno":42,"subject":"数据结构","type":"AOE网关键路径","title":"AOE网关键路径与工期压缩","score":"（未标）","budgetMin":"10","detail":"本题按 AOE 网求关键路径与可压缩量：活动最早结束时间为 12，关键活动是 a、e、m、n；与 e 并行的活动为 b、c、d；余量最大的活动 j 余量为 6，因此优先把 b 压缩到 4，否则改压 k 到 1。考场先正推各顶点最早时间、逆推最迟时间，再用 e(i)=l(i) 判关键活动，不要把 h、k 误算成关键活动，也别漏写并行的 c 或 d。","kp":["AOE网","关键路径","最早最迟时间","活动余量"],"answerKey":["活动最早结束时间12","关键活动a、e、m、n","与e并行活动：b、c、d","活动余量最大为6，属活动j","b压缩到4；否则压缩k到1"],"mustWrite":["写关键路径与12","并行活动列全","压缩量与对象写清"],"skip":["不用写AOE网存储结构"],"pitfalls":["把h、k算成关键活动","并行活动漏写c或d"]},{"year":2025,"qno":43,"subject":"计算机组成原理","type":"Cache与虚拟存储","title":"Cache与虚存综合计算","score":"（未标）","budgetMin":"12","detail":"综合题把 Cache 与虚存两条链串起来：64 组对应组号 6 位、块内地址 6 位，取虚地址的 V11~V6 作组索引；d[100] 的 VA=0180 01B0H 落在组号 06H。缺失率按 129/4096=3.15% 计算，平均访问时间约 8.3；d 分布在 3 页，缺页 3 次。考场先固定“块大小→块内位数、组数→组号位数”的换算，再逐项套公式，别把组数算成 512。","kp":["Cache映射","组相联","页表","缺页"],"answerKey":["组数64→组号6位、块内地址6位；VA中V11~V6作索引","d[100]的VA=0180 01B0H，组号06H","缺失率129/4096=3.15%，平均访问时间≈8.3","d分布3页，缺页3次"],"mustWrite":["写6位/6位与索引V11~V6","写VA与组号","写缺失率3.15%与8.3","写3页与缺页3次"],"skip":["不用写替换算法"],"pitfalls":["组数算成512组"]},{"year":2025,"qno":44,"subject":"计算机组成原理","type":"补码除法器与异常","title":"补码除法器与异常响应","score":"（未标）","budgetMin":"12","detail":"本题考补码除法器的执行结果与两类异常：结果 R=FFFFFFFFH、Q=87654321H、Y=FFFFFFFFH；控制逻辑中含计数器，ALU 的运算为加法与减法。除数为 0 时 d[i] 任意、x=0000 0000H；溢出对应 -2^31÷(-1)，此时 d[i]=8000 0000H、x=FFFF FFFFH。异常响应要写全关中断、转内核态、保存断点（PC/PSWR）、转异常处理四步，ALU 只写加法会直接丢分。","kp":["补码除法","除数为0","溢出异常","中断响应"],"answerKey":["R=FFFF FFFFH、Q=87654321H、Y=FFFFFFFFH","b控制逻辑含计数器；ALU运算为加法与减法","除数为0：d[i]任意，x=0000 0000H","溢出：d[i]=8000 0000H、x=FFFF FFFFH（-2³¹÷-1）","响应：关中断、转内核态、保存断点(PC/PSWR)、转异常处理"],"mustWrite":["三寄存器值分写带H","ALU写加法与减法","异常响应三步写全"],"skip":["不用写逐拍过程"],"pitfalls":["ALU只写加法"]},{"year":2025,"qno":45,"subject":"操作系统","type":"同步互斥（PV操作）","title":"挖坑填土浇水的PV同步","score":"（未标）","budgetMin":"10","detail":"三人协作：甲挖坑、乙填土、丙浇水，本质是带缓冲的生产者—消费者链。mutexT=1 管那把铁锹，sk=3 表示可用的坑位数量，empty=0、water=0 则串起“挖好才能填、填好才能浇”。考场做法就是先数清资源种类与上限（坑位为 3 这一点最易漏），再给每种资源配一个信号量，把 wait 放在使用之前、signal 放在产出之后。","kp":["PV操作","信号量","生产者消费者","同步互斥"],"answerKey":["mutexT=1(铁锹)、sk=3(坑数)、empty=0、water=0","甲 wait(sk)/mutexT 挖坑 signal(mutexT/empty)","乙 wait(empty/mutexT) 填土 signal(mutexT/sk/water)","丙 wait(water) 浇水"],"mustWrite":["4个信号量名+初值"],"skip":["不用写水桶互斥"],"pitfalls":["漏sk=3"]},{"year":2025,"qno":46,"subject":"操作系统","type":"进程地址空间与I/O","title":"进程地址空间与I/O调用","score":"（未标）","budgetMin":"10","detail":"本题要求把程序里的对象放回进程地址空间：PCB 在内核区，main() 的代码在只读代码段，ptr 变量本身在可读写数据段，length 在用户栈，ptr 指向的字符串在运行时堆；执行 scanf() 时进程处于阻塞态，scanf 与 printf 都要经由驱动程序完成 I/O。答题关键是区分“指针变量本身”与“指针指向的对象”，这两问最容易互相串错。","kp":["进程控制块","地址空间","阻塞态","堆与栈"],"answerKey":["PCB位于内核区；执行scanf()时进程处于阻塞态","main()代码在只读代码段","scanf()、printf()需执行驱动程序","ptr在可读写数据段，length在用户栈，ptr指向的字符串在运行时堆"],"mustWrite":["答PCB位置与阻塞态","答各代码/数据位置","答scanf与printf调驱动"],"skip":["不用写系统调用细节"],"pitfalls":["把ptr指针本身答成堆","把length答成数据段"]},{"year":2025,"qno":47,"subject":"计算机网络","type":"卫星链路/窗口/子网划分","title":"卫星链路时延与子网划分","score":"（未标）","budgetMin":"12","detail":"这题一半通信原理、一半子网划分：卫星 36000km 单程时延约 0.12s；吞吐量按“帧/(传播时延+帧/带宽)”计算，上传量为 32000/带宽；窗口 N 由带宽×时延/帧再乘系数得出，序号位数至少 2N。子网部分按需求倒推前缀：生活区需 120 个地址用 /27（126 可用），另两区需 60 个用 /26（62 可用），10.10.10.0/24 可划 8 个 /27 或 4 个 /26。别忘了每个子网要减 2。","kp":["传播时延","吞吐量","滑动窗口","子网划分"],"answerKey":["时延≈0.12s(36000÷300000km/s)","吞吐量=帧/(传播时延+帧/带宽)；上传=32000/带宽","窗口N=带宽×时延/帧×系数，序号≥2N","生活区/27(126≥120)，另两区/26(62≥60)","10.10.10.0/24可划8个/27或4个/26"],"mustWrite":["写时延≈0.12s与两个公式","写/27、/26及减2"],"skip":["不用写首部开销"],"pitfalls":["忘换算比特"]},{"year":2026,"qno":41,"subject":"数据结构","type":"算法设计题","title":"二叉搜索树最小差值","score":"13分","budgetMin":"13","detail":"要在一棵二叉搜索树中找差值最小的两个关键字。BST 的中序遍历是递增序列，最小差值必出现在相邻两个被访问的结点之间：只需维护上一个最小值 min，边遍历边算差值，diff<min 就更新、diff==min 就记录下来（最多 2 个），一旦 diff>min 说明后续只会更大，用 flag 终止递归剪枝。考场先讲清“中序有序”这个前提，再补上剪枝，并且说明最多只有两个结点满足，否则容易只输出一个。","kp":["二叉搜索树","中序遍历","递归","剪枝"],"answerKey":["中序遍历BST得递增序列","维护最小值min：diff<min更新，diff==min记录（最多2个）","diff>min时后续更大，flag终止递归","输出min与全部满足条件的关键字"],"mustWrite":["写：BST中序为递增序列","写：维护min并记录差值为min的≤2个结点","写：中序递归+flag剪枝的C代码"],"skip":["不用写：建树/删除代码","不用写：非递归实现"],"pitfalls":["只输出一个结点","未说明剪枝/最多两个"]},{"year":2026,"qno":42,"subject":"数据结构","type":"出栈序列判定","title":"出栈序列合法性与计数","score":"10分","budgetMin":"10","detail":"本题考入栈出栈序列的可行性判据：若存在 i<j<k 使 Pj<Pk<Pi（即 312 模式），该出栈序列就不可能由栈得到。前一序列含 4、5、7 构成的 312 模式故不能，后一序列可以；计数部分用卡特兰结构：n=4 且以 2 开头共 5 个，以 1、2 开头各 M 个，总数按 2(2k-1)/(k+1)·M 给出。考场先答“能/不能”并指名具体下标，再写计数公式，只丢结论不给下标是常见丢分点。","kp":["栈","出栈序列","卡特兰数","312模式"],"answerKey":["(1)前一序列不能：有i=4,j=5,k=7使4<5<6（312模式）；后一序列可以","(2)必存在i<j<k使Pj<Pk<Pi","(3)n=4以2开头共5个","(4)以1、2开头各M个；总数=2(2k-1)/(k+1)·M"],"mustWrite":["写：两个结论+312模式反例","写：5个、M、M与总数公式"],"skip":["不用写：完整卡特兰数推导"],"pitfalls":["只答能/不能不给下标"]},{"year":2026,"qno":43,"subject":"计算机组成原理","type":"编码计算","title":"指令位域与寄存器编码","score":"10分","budgetMin":"10","detail":"本题从编码空间反推硬件规模：主存单元 8 位、通用寄存器 16 位；op1 与 op2 的位域不同所以可以相同，op2 与 op3 位域相同所以不可能相同。随后按指令语义算出 R2=9BCEH，而 R9=F001H 保持不变。最后一问直接写四个二进制片段，注意那是 R15+2，偏移量 2 不能漏。","kp":["指令格式","位域","通用寄存器","符号扩展"],"answerKey":["(1)主存单元8位，通用寄存器16位","op1与op2可同（位域异）；op2与op3不可（位域同）","(3)R2=9BCEH；R9=F001H不变","(4)①1110 ②00000100 ③11111011 ④000000000010"],"mustWrite":["写：8位/16位及理由","写：可以/不可+位域理由","写：9BCEH、R9不变","写：①~④四个二进制片段"],"skip":["不用写：4条指令逐位展开"],"pitfalls":["④漏偏移2（R15+2）"]},{"year":2026,"qno":44,"subject":"计算机组成原理","type":"通路信号","title":"数据通路控制信号取值","score":"13分(另注15分)","budgetMin":"13","detail":"本题给出带多路选择器的数据通路，先要判断 ①、② 都是多路选择器，并说明 EXTOP 至少 2 位才能区分符号扩展、零扩展与 offset12 符号扩展三种情形。控制信号要按指令逐拍填：取指时 MARSrC=0、ALUASrc=0、ALUBSrc=1、RegWr=0；左移时 ALUBSrc=2、RegWSrc=1、RegDst=1、RegWr=1。考场先由“取指阶段不写回寄存器”排除 RegWr=1，再逐项顺着数据流向定值。","kp":["数据通路","多路选择器","控制信号","扩展方式"],"answerKey":["①、②为多路选择器","EXTOP≥2位：符号/零扩展、offset12符号扩展3种","取指:MARSrC=0,ALUASrc=0,ALUBSrc=1,RegWr=0","左移:ALUBSrc=2,RegWSrc=1,RegDst=1,RegWr=1"],"mustWrite":["写：多路选择器","写：2位+三种扩展","写：取指/左移各四个取值"],"skip":["不用写：通路连线细节"],"pitfalls":["EXTOP只答1位；取指RegWr误写1"]},{"year":2026,"qno":45,"subject":"操作系统","type":"调度模拟","title":"时钟中断驱动的时间片调度","score":"7分","budgetMin":"10","detail":"本题按时钟中断驱动的调度模拟：10~220ms 内共 22 次中断，其中发生 7 次调度（在 10、20、70、80、90、140、180ms）；首次调度时刻分别为 P2@10、P4@20、P1@90、P3@140ms。第二问改参数：时间片 50→100ms 使调度次数减少，中断周期 10→1ms 使中断开销增大。考场要牢记抢占只发生在时钟中断点、同优先级按先来先服务，别在 14ms 处误判抢占。","kp":["进程调度","时间片","时钟中断","抢占"],"answerKey":["(1)中断22次（10~220ms）；调度7次（10,20,70,80,90,140,180ms）","首次调度：P2@10、P4@20、P1@90、P3@140ms","(2)时间片50→100ms调度次数减少；中断10→1ms开销增大"],"mustWrite":["写：22次、7次","写：四个首次调度时刻","写：减少/增大及理由"],"skip":["不用写：完整甘特图推演"],"pitfalls":["抢占只在时钟中断，误在14ms抢占；同优先级未按先来先服务"]},{"year":2026,"qno":46,"subject":"操作系统","type":"索引节点分析","title":"索引节点与磁盘块定位","score":"8分","budgetMin":"10","detail":"先由 4096/128=32 得每个盘块可放 32 个索引节点，故节点 1000 落在盘块 131；21460 位于逻辑块 5（直接项 0~4 之后），需读间接块加数据块共 2 块；单个文件最多 131072 块。删除 file 时要释放数据块与间接块本身、把两处位示图清零、删掉 dir1 中的目录项；删除 dir1 还要释放目录块并回到父目录删其目录项。考场最易漏“间接块本身也要释放”和“要改父目录”。","kp":["索引节点","混合索引","位示图","目录项"],"answerKey":["(1)4096/128=32→节点1000在盘块131","21460在逻辑块5（直接项0~4）→读间接块+数据块=2块","最多文件数131072","(2)删file：释放数据块及间接块、两处位示图清零、dir1目录项删除","删dir1：释放目录块、位图清零、父目录删其目录项"],"mustWrite":["写：131、2块、131072","写：位示图清零+目录项删除"],"skip":["不用写：块大小重复推导"],"pitfalls":["漏间接块本身释放；忘改父目录"]},{"year":2026,"qno":47,"subject":"计算机网络","type":"TCP计算","title":"TCP握手与拥塞窗口","score":"9分","budgetMin":"12","detail":"本题把 TCP 建连、发送、断链、时延串成一条线：三次握手完成，确认序号 1001；拥塞窗口增至 1500B，但发送窗口要取 min(cwnd, rwnd)=1000B；四次挥手末段 FIN=1、seq=2001、ack=3002；总时延为 1RTT 建连加 3RTT 传输共 20ms。考场关键是记住 SYN 与 FIN 各占一个序号，以及发送窗口永远取拥塞窗口与接收窗口的较小值。","kp":["TCP三次握手","拥塞窗口","发送窗口","四次挥手"],"answerKey":["(1)三次握手；确认序号1001","(2)cwnd增至1500B；发送窗口取min=1000B","(3)四次挥手；末段FIN=1、seq=2001、ack=3002","(4)1RTT建连+3RTT传输=20ms"],"mustWrite":["写：三次握手、1001","写：1500B与1000B取min","写：四次挥手与seq/ack/FIN","写：20ms"],"skip":["不用写：时序图"],"pitfalls":["忘SYN/FIN占序号；发送窗口误写1500B"]}];
